export const SKILL_FILES: Record<string, string> = {
 "pce-poem/SKILL.md": "---\nname: pce-poem\ndescription: Compose song lyrics or a poem with the Pratyabhijna cascade protocol (constraint anchoring, K-candidate generation, contrastive exclusion of cliches, aspect-conditioned selection, vimarsa aspect-shift gate and a shadow revision pass). Use for any lyric, verse, haiku, sonnet or short literary form.\n---\n\n# pce-poem - cloud port of the Pratyabhijna `pce-poem` workflow\n\nPort of `SharathSPhD/pratyabhijna` -> `plugin/commands/poem.md` + `agents/poet.md` +\n`skills/cascade-poetry`. The original calls an MCP `cascade` tool backed by a Python\nengine (local LM, sentence embeddings, Dirichlet BMR). That engine cannot run in this\nsandbox, so each operator is carried out here as an explicit, auditable step. See\n`FIDELITY.md` in the repo for what is and is not equivalent. Never skip a step and never\nreturn a poem produced by a single un-scored draw.\n\n## Inputs\n- `topic` - the brief, <= 30 words (distil longer briefs).\n- `form` - e.g. haiku | sonnet | free | song sections (pallavi/anupallavi/charanam, mukhda/antara, verse/chorus...).\n- `language` - write natively in the target script and idiom; do not translate from English.\n- `must_avoid` - cliches to dodge (always add the genre's stock images: e.g. \"moon/rain/heart\" pairings the user did not ask for).\n- `K` - candidate count (tier-dependent; default 3, pro 6) and `revise` (true/false).\n\n## Engine mode (preferred when `EMBED_URL` and `EMBED_TOKEN` are given in the kickoff)\nThis skill ships the real Pratyabhijna engine (`run_cascade.py` + package `pce/`, Python 3.11, numpy/scipy are preinstalled).\nThe engine directory is `ENGINE=/workspace/skills/pce-poem` (check `ls $ENGINE/run_cascade.py`; if missing use `find /workspace -maxdepth 3 -name run_cascade.py`, never `find /`).\nYou are the language model; the engine does every scoring step (apohana, ananda, jnana BMR, vimarsa gate, commit policy).\n1. `mkdir -p /mnt/session/work/pce && cd` there. Write `brief.json`:\n   `{\"topic\": <brief, <=30 words>, \"constraint\": <step-1 line>, \"must_avoid\": [...], \"aspects\": [2-4 short phrases], \"K\": <3 free | 6 pro>, \"seed\": 0}`\n   (`aspects` as short natural phrases; the embedder is multilingual so English aspects are fine.)\n2. `export EMBED_URL=... EMBED_TOKEN=...` (from the kickoff) and run `python3 $ENGINE/run_cascade.py /mnt/session/work/pce`.\n3. Exit code 3 = it needs text: read `needs.json`. It lists `prompts` (one per candidate; each begins with its own small nudge).\n   Write one complete candidate per prompt, in order, in the target language/script, into `generations.json` under the key named by `kind`\n   (`{\"draft\": [...], \"revision\": [...]}`, keep earlier keys). Pro tier: delegate each candidate to PCE Poet in parallel, then wait with a loop that exits as soon as all files exist (`for i in $(seq 1 60); do [ $(ls cand_*.md 2>/dev/null | wc -l) -ge N ] && break; sleep 3; done`), never a fixed long sleep. Re-run step 2.\n4. Exit code 0 = `result.json`. `surface` is the committed lyric (`committed` = draft|revision; revision is only taken if vimarsa fired).\n   Copy `surface` into `/mnt/session/outputs/lyrics.md` (sectioned for singing) and `result.json` to `/mnt/session/outputs/cascade_audit.json`.\nNever edit the engine or its numbers. If `EMBED_URL` is absent or the service errors twice, say so in the audit and use the manual cascade below.\n\n## Cascade (manual fallback)\n1. **constraint** - write one line (<= 20 words) naming form, tone, language, singable meter. Pick 2-4 `aspects` (semantic axes the user implied; never invent ones they did not).\n2. **iccha - K candidates.** Produce K candidate drafts that share the same brief and constraint and differ only by seed/angle (different opening image, different aspect emphasis). With a worker agent available, spawn one per candidate (self-contained brief, write to `/mnt/session/work/cand_<k>.md`). Do not tune the prompt per candidate.\n3. **apohana - contrastive exclusion.** For each candidate score 0-1: closeness to the constraint minus its closeness to the nearest `must_avoid` exemplar. Min-max normalise across the K candidates so a cliche-heavy draft loses mass instead of tying.\n4. **ananda - aesthetic coherence.** Score 0-1 each: coherence to the constraint, diversity (no repeated lines/rhyme words), form fidelity (syllable/meter/section structure actually met - count it), singability. Average.\n5. **jnana - selection.** posterior_k proportional to `1 + 1.0*ananda_k + 1.0*apoha_k` (+ `0.5` per `aspect` the candidate realises when aspects were given). Pick argmax; record the table in `/mnt/session/outputs/cascade_audit.json` (scores per candidate, selected index).\n6. **vimarsa - aspect-shift gate.** Fire (event = true) iff ALL: novelty vs. the median of the other candidates >= 0.30, >= 1 aspect realised, ananda >= 0.40, and the draft's score gain over the median >= 0.05. Record `vimarsa_event` and one sentence on which aspects fired.\n7. **kriya - enactment + shadow revision.** `revise=false`: emit the selected draft verbatim. `revise=true`: always write a revision from the vimarsa brief (keep what fired, remove the nearest must-avoid, fix failed form checks), then commit the revision iff vimarsa fired, else commit the draft. Record `committed: draft|revision`.\n\n## Output\nWrite `/mnt/session/outputs/lyrics.md` (the committed surface only, sectioned for singing) and `cascade_audit.json`. Return only the lyrics plus, if vimarsa fired, one italic line naming the aspects.\n\n## Anti-patterns\n- Do not return a lyric that has not passed steps 3-6.\n- Do not pad lyrics with translation or commentary; no markdown inside lyric lines.\n- Do not use a hardcoded cliche list as the only `must_avoid`; derive it from the brief.\n",
 "pce-poem/.pytest_cache/README.md": "# pytest cache directory #\n\nThis directory contains data from the pytest's cache plugin,\nwhich provides the `--lf` and `--ff` options, as well as the `cache` fixture.\n\n**Do not** commit this to version control.\n\nSee [the docs](https://docs.pytest.org/en/stable/how-to/cache.html) for more information.\n",
 "pce-poem/bench/embedder_bench.py": "import numpy as np, onnxruntime as ort, sys\nfrom tokenizers import Tokenizer\nsys.path.insert(0,'/home/user/neo-fm/services/embedder')\ndef load(path_model, path_tok, pad):\n    s=ort.InferenceSession(path_model,providers=[\"CPUExecutionProvider\"])\n    t=Tokenizer.from_file(path_tok); t.enable_truncation(max_length=256); t.enable_padding(pad_id=t.token_to_id(pad) or 0,pad_token=pad)\n    return s,t\ndef run(s,t,texts,pool):\n    enc=t.encode_batch(texts); ids=np.array([e.ids for e in enc],dtype=np.int64); m=np.array([e.attention_mask for e in enc],dtype=np.int64)\n    feeds={\"input_ids\":ids,\"attention_mask\":m}\n    names=[i.name for i in s.get_inputs()]\n    if \"token_type_ids\" in names: feeds[\"token_type_ids\"]=np.zeros_like(ids)\n    outs=s.run(None,feeds)\n    onames=[o.name for o in s.get_outputs()]\n    if pool==\"sentence\" and \"sentence_embedding\" in onames: v=outs[onames.index(\"sentence_embedding\")]\n    else:\n        h=outs[0]; mm=m[...,None].astype(np.float32); v=(h*mm).sum(1)/np.clip(mm.sum(1),1e-9,None)\n    return v/np.clip(np.linalg.norm(v,axis=1,keepdims=True),1e-9,None)\n# (aspect/query in English, positive lyric line, hard-negative lyric lines in other themes), per language\nDATA={\n\"kn\":[(\"longing for home\",\"ಮಳೆ ಬಂತು ಮನೆ ನೆನಪಾಯ್ತು ಅಮ್ಮನ ಸೆರಗಿನ ಘಮ ಗಾಳಿಯಲಿ\",\"ಕ್ರಿಕೆಟ್ ಪಂದ್ಯದಲ್ಲಿ ನಮ್ಮ ತಂಡ ಗೆದ್ದಿತು\"),(\"devotion to the goddess\",\"ತಾಯಿ ಚಾಮುಂಡಿ ನಿನ್ನ ಪಾದಕೆ ನಮಿಸುವೆ ಕಾಪಾಡು\",\"ಮಾರುಕಟ್ಟೆಯಲ್ಲಿ ತರಕಾರಿ ಬೆಲೆ ಏರಿದೆ\"),(\"dawn over the temple tank\",\"ಬೆಳಗಿನ ಕಿರಣ ಕೊಳದ ಮೇಲೆ ಚಿನ್ನ ಚೆಲ್ಲಿತು ಗುಡಿಯ ಘಂಟೆ ಮೊಳಗಿತು\",\"ರೈಲು ನಿಲ್ದಾಣದಲ್ಲಿ ಜನಸಂದಣಿ ಇತ್ತು\")],\n\"ta\":[(\"longing for home\",\"மழை வந்ததும் என் வீடு நினைவுக்கு வந்தது அம்மாவின் மணம் காற்றில்\",\"கிரிக்கெட் போட்டியில் அணி வெற்றி பெற்றது\"),(\"harvest festival joy\",\"பொங்கல் பானை பொங்கி வழிய உழவர் மகிழ்ந்து பாடினர்\",\"அலுவலக கூட்டம் நாளை காலை நடைபெறும்\"),(\"a mother's lullaby\",\"கண்ணே கண்ணுறங்கு அம்மா பாடுவேன் தாலாட்டு\",\"பங்குச் சந்தை இன்று சரிந்தது\")],\n\"te\":[(\"longing for home\",\"వర్షం కురిసింది ఇంటి జ్ఞాపకం వచ్చింది అమ్మ చీర వాసన గాలిలో\",\"క్రికెట్ మ్యాచ్‌లో మన జట్టు గెలిచింది\"),(\"devotion to Lord Rama\",\"రామ నామ జపము చేయుచుండె మనసు భక్తితో\",\"బ్యాంకు వడ్డీ రేట్లు పెరిగాయి\"),(\"spring blossoms\",\"వసంతం వచ్చింది మామిడి పూలు విరిసాయి కోకిల పాడింది\",\"ట్రాఫిక్ జామ్ వల్ల ఆలస్యమైంది\")],\n\"hi\":[(\"longing for home\",\"बारिश आई तो घर की याद आई माँ के आँचल की खुशबू हवा में\",\"क्रिकेट मैच में हमारी टीम जीत गई\"),(\"love under the monsoon\",\"भीगी सड़कों पर तेरा इंतज़ार करता रहा बादल गरजे\",\"शेयर बाज़ार आज गिर गया\"),(\"devotion to Krishna\",\"मुरली की धुन पर नाचे राधा कृष्ण के संग\",\"दफ्तर की बैठक कल सुबह होगी\")],\n\"bn\":[(\"longing for home\",\"বৃষ্টি এলো ঘরের কথা মনে পড়লো মায়ের আঁচলের গন্ধ হাওয়ায়\",\"ক্রিকেট ম্যাচে আমাদের দল জিতেছে\"),(\"rain and the river\",\"নদীর বুকে বৃষ্টি ঝরে সন্ধ্যা নামে ধীরে\",\"শেয়ার বাজার আজ পড়ে গেছে\"),(\"autumn festival\",\"শরতের আকাশে কাশফুল দুর্গাপূজার ঢাক বাজে\",\"অফিসের মিটিং কাল সকালে\")],\n}\ndef evaluate(name,enc):\n    ok=0;n=0;margins=[]\n    for lang,items in DATA.items():\n        for idx,(q,pos,neg) in enumerate(items):\n            # cross-lingual: English aspect vs poem line (positive should beat unrelated negative)\n            qv=enc(\"query\",[q]); dv=enc(\"doc\",[pos,neg,*[its[j][1] for l2,its in DATA.items() if l2!=lang for j in range(3) if j!=idx and j!=0 and idx!=0]])\n            s=(qv@dv.T)[0]; n+=1; ok+= int(s[0]>s[1:].max()); margins.append(float(s[0]-s[1:].max()))\n    print(f\"{name}: top1 {ok}/{n}  mean margin {np.mean(margins):.3f}\")\n# e5\ns1,t1=load('/models/e5/model_quantized.onnx','/models/e5/tokenizer.json','<pad>')\nevaluate(\"e5-small\",lambda k,x: run(s1,t1,[(\"query: \" if k==\"query\" else \"passage: \")+a for a in x],\"mean\"))\ns2,t2=load('/models/gemma/model_quantized.onnx','/models/gemma/tokenizer.json','<pad>')\nprint([o.name for o in s2.get_outputs()])\nevaluate(\"embeddinggemma-300m\",lambda k,x: run(s2,t2,[(\"task: search result | query: \" if k==\"query\" else \"title: none | text: \")+a for a in x],\"sentence\"))\n",
 "pce-poem/pce/__init__.py": "\"\"\"Pratyabhijna Creative Engine (PCE).\n\nPublic API entry points are added in Phase 5 once the operator implementations land.\nFor Phase 3 the package only needs to be importable so the project's smoke check\n(`python -c \"import pce\"`) succeeds.\n\"\"\"\nfrom __future__ import annotations\n\n__version__ = \"0.1.0\"\n__all__ = [\"__version__\"]\n",
 "pce-poem/pce/active_inference/__init__.py": "\"\"\"Active-inference machinery used by the v0.3 cascade.\n\nThree pieces live here:\n\n* :class:`pce.active_inference.hopfield.HopfieldStore` -- the storehouse\n  consciousness (ālaya-vijñāna) component the cascade calls into during\n  :func:`pce.operators.apohana.apohana` for warm-start aspect priors and that\n  :func:`pce.operators.vimarsa.consolidate` writes back to at the end of every\n  prompt (REM-style fast write or SWS-style slow consolidation).\n* :class:`pce.active_inference.budget.FreeEnergyBudget` -- a per-item ledger\n  that pays/earns free energy from (a) ΔF reported by jñāna BMR, (b) embedding\n  distance between the surface and the constraint/aspect prior, and (c) the\n  committed token count. The cascade aborts the revision pass if the ledger\n  drops below the abort threshold.\n* The aspect-conditioned BMR reductions live in :mod:`pce.operators.jnana`\n  itself (``reduction_target=\"aspect_conditioned\"``) so the BMR posterior and\n  the aspect prior live in one place; this package only owns the storehouse\n  and the budget that the cascade consults from the outside.\n\nPer ADR-003 / ADR-004 / ADR-005 the storehouse is per-domain, REM-mode is\ndeterministic-on-input (so cascade runs are reproducible), and the budget\nledger is per-item (no cross-prompt budget bleed).\n\"\"\"\nfrom pce.active_inference.budget import (\n    BudgetExceededError,\n    BudgetLedgerEntry,\n    FreeEnergyBudget,\n)\nfrom pce.active_inference.hopfield import HopfieldStore\n\n__all__ = [\n    \"BudgetExceededError\",\n    \"BudgetLedgerEntry\",\n    \"FreeEnergyBudget\",\n    \"HopfieldStore\",\n]\n",
 "pce-poem/pce/active_inference/budget.py": "\"\"\"Per-item free-energy budget ledger.\n\nThe cascade pays/earns *bits of free energy* across the cit-iccha-jnana-vimarsa\nsequence. The ledger has three signed contributors:\n\n1. ``earn_jnana(delta_F)`` -- jñāna BMR ΔF (bits of evidence the surface\n   actually fits the constraint posterior). Positive ΔF earns budget.\n2. ``earn_aspect(distance)`` -- the embedding cosine *distance* (= 1 - cosine)\n   between the committed surface and the aspect prior. Lower distance =>\n   smaller cost; higher distance is a cost the cascade pays.\n3. ``earn_tokens(n_tokens)`` -- a flat per-token cost of\n   ``self.token_cost_bits`` bits/token. Always negative.\n\nWhen ``balance() <= abort_threshold`` the cascade is told to skip the\nrevision pass via :meth:`should_continue_revision`. The default\n``abort_threshold = -2.0`` corresponds to \"the surface costs ~3 bits more\nthan the BMR earned, and the second pass would only widen the gap unless\nthe brief is tight\". The threshold is conservative because revision passes\nin v0.2 always helped the prove-gate items.\n\nThe ledger is per-prompt: the cascade creates one\n:class:`FreeEnergyBudget` at the top of ``run_cascade`` and discards it at\nthe bottom. There is *no* cross-prompt budget bleed; the per-domain\nstorehouse is the only stateful component.\n\"\"\"\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Literal\n\n\nclass BudgetExceededError(RuntimeError):\n    \"\"\"Raised when a caller tries to keep going past ``abort_threshold``.\n\n    The cascade catches this and either commits the draft (if event-gated\n    skipped revision because of cost) or surfaces it to the audit log.\n    \"\"\"\n\n\n@dataclass(frozen=True)\nclass BudgetLedgerEntry:\n    \"\"\"One signed entry in the per-item budget ledger.\"\"\"\n\n    source: Literal[\"jnana\", \"aspect\", \"tokens\", \"manual\"]\n    bits: float\n    note: str = \"\"\n\n\n@dataclass\nclass FreeEnergyBudget:\n    \"\"\"Per-item free-energy ledger.\n\n    Default constants are calibrated against the v0.2 audit (mean draft pass:\n    ~110 tokens; mean ΔF: ~0.2 bits; mean aspect cosine: ~0.45). The\n    revision pass is allowed when there is at least ~2 bits of headroom.\n    \"\"\"\n\n    initial_bits: float = 4.0\n    abort_threshold: float = -2.0\n    token_cost_bits: float = 0.01  # ~1 bit per 100 tokens\n    aspect_cost_scale: float = 2.0\n    jnana_earn_scale: float = 1.0\n    entries: list[BudgetLedgerEntry] = field(default_factory=list)\n\n    def balance(self) -> float:\n        \"\"\"Total bits remaining (initial + sum of signed entries).\"\"\"\n        return float(self.initial_bits + sum(e.bits for e in self.entries))\n\n    def earn_jnana(self, delta_F: float, *, note: str = \"\") -> float:\n        \"\"\"Add (signed) jñāna ΔF to the ledger; clipped to a safe range.\"\"\"\n        bits = float(self.jnana_earn_scale * float(delta_F))\n        bits = max(-10.0, min(10.0, bits))  # clip to avoid -inf cascading\n        self.entries.append(BudgetLedgerEntry(source=\"jnana\", bits=bits, note=note))\n        return self.balance()\n\n    def earn_aspect(self, distance: float, *, note: str = \"\") -> float:\n        \"\"\"Pay aspect cost: -aspect_cost_scale * distance bits.\"\"\"\n        d = max(0.0, float(distance))\n        bits = -float(self.aspect_cost_scale * d)\n        self.entries.append(BudgetLedgerEntry(source=\"aspect\", bits=bits, note=note))\n        return self.balance()\n\n    def earn_tokens(self, n_tokens: int, *, note: str = \"\") -> float:\n        \"\"\"Pay flat per-token cost: -token_cost_bits * n_tokens bits.\"\"\"\n        n = max(0, int(n_tokens))\n        bits = -float(self.token_cost_bits * n)\n        self.entries.append(BudgetLedgerEntry(source=\"tokens\", bits=bits, note=note))\n        return self.balance()\n\n    def add_manual(self, bits: float, *, note: str = \"\") -> float:\n        \"\"\"Add a caller-supplied signed adjustment (used by tests/debug).\"\"\"\n        self.entries.append(BudgetLedgerEntry(source=\"manual\", bits=float(bits), note=note))\n        return self.balance()\n\n    def should_continue_revision(self) -> bool:\n        \"\"\"True iff the ledger still has headroom for a revision pass.\"\"\"\n        return self.balance() > self.abort_threshold\n\n    def to_audit(self) -> dict[str, object]:\n        \"\"\"Render the ledger for inclusion in :class:`pce.types.CascadeState.audit`.\"\"\"\n        return {\n            \"initial_bits\": float(self.initial_bits),\n            \"abort_threshold\": float(self.abort_threshold),\n            \"token_cost_bits\": float(self.token_cost_bits),\n            \"aspect_cost_scale\": float(self.aspect_cost_scale),\n            \"jnana_earn_scale\": float(self.jnana_earn_scale),\n            \"balance_bits\": float(self.balance()),\n            \"entries\": [\n                {\"source\": str(e.source), \"bits\": float(e.bits), \"note\": str(e.note)}\n                for e in self.entries\n            ],\n        }\n",
 "pce-poem/pce/active_inference/hopfield.py": "\"\"\"Modern continuous Hopfield store -- the storehouse (ālaya-vijñāna) layer.\n\nThe store owns a per-domain matrix of unit-norm aspect/surface embeddings.\n``query`` returns the softmax-attended retrieval over the matrix (Ramsauer et\nal. 2020, *Hopfield Networks Is All You Need*) so callers can use it as a\nwarm-start prior. ``write`` appends a new pattern (REM mode) or replaces the\nnearest existing pattern (SWS / slow-consolidation mode); ``persist`` writes\nthe matrix to ``audit/storehouse/<domain>.npz``.\n\nOnly the v0.3 cascade calls into this store: :func:`pce.operators.apohana.apohana`\nqueries it for warm-start aspect mass and :func:`pce.operators.vimarsa.consolidate`\nwrites back the committed surface at the end of every prompt. The storehouse\nis reset between domains for the benchmark so prompts within a domain share\ncontext but cross-domain runs stay independent.\n\nMathematically the lookup is\n\n.. math::\n\n    p_i = \\\\text{softmax}(\\\\beta\\\\, X x)_i, \\\\quad \\\\hat{x} = X^\\\\top p\n\nwhere ``X`` is the (N, D) row-normalized pattern matrix, ``x`` is the unit\nquery, and ``β`` is an inverse-temperature (default 8.0). The retrieval\n\"energy\" we expose to apohana is the negative log-sum-exp value\n``-1/β · logsumexp(β X x)``: lower is more confidently retrieved (closer to\na stored aspect), higher is more diffuse / novel.\n\"\"\"\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Literal\n\nimport numpy as np\nimport numpy.typing as npt\n\nWriteMode = Literal[\"rem\", \"sws\"]\nEmbeddingArray = npt.NDArray[np.float32]\n\n\ndef _l2_normalize(x: npt.NDArray[np.float32]) -> npt.NDArray[np.float32]:\n    \"\"\"Row-wise L2 normalize (1D treated as a single row).\"\"\"\n    arr = np.asarray(x, dtype=np.float32)\n    if arr.ndim == 1:\n        n = float(np.linalg.norm(arr) + 1e-12)\n        out: npt.NDArray[np.float32] = (arr / n).astype(np.float32)\n        return out\n    norms = np.linalg.norm(arr, axis=1, keepdims=True)\n    norms = np.maximum(norms, 1e-12)\n    out2: npt.NDArray[np.float32] = (arr / norms).astype(np.float32)\n    return out2\n\n\n@dataclass(frozen=True)\nclass HopfieldQueryResult:\n    \"\"\"The result of one :meth:`HopfieldStore.query` call.\"\"\"\n\n    n_patterns: int\n    \"\"\"Number of stored patterns at query time (0 if the store is empty).\"\"\"\n\n    energy: float\n    \"\"\"The Hopfield retrieval energy, ``-1/β · logsumexp(β · X x)``.\n\n    Smaller (more negative) values indicate confident retrieval; ``+inf``\n    means the store is empty so no warm-start is available.\n    \"\"\"\n\n    attention: npt.NDArray[np.float32]\n    \"\"\"The softmax over stored patterns; shape ``(N,)``. Empty array if N=0.\"\"\"\n\n    retrieved: EmbeddingArray\n    \"\"\"The convex combination of stored patterns under ``attention``;\n    shape ``(D,)``. Equal to the query when N=0 (zero-warm-start fallback).\"\"\"\n\n    aspect_priors: npt.NDArray[np.float32]\n    \"\"\"One scalar per *aspect* in the per-query aspect set, giving the mass\n    that the storehouse softmax assigns to patterns labelled with that\n    aspect. Used by jñāna BMR aspect-conditioned reductions and by apohana\n    as a warm-start mixture weight. Shape ``(A,)`` where A is the number\n    of aspects supplied to :meth:`query`. Empty when no aspects supplied.\"\"\"\n\n\nclass HopfieldStore:\n    \"\"\"Per-domain modern Hopfield storehouse.\n\n    The store is created either fresh (``HopfieldStore(domain=\"poetry_gen\")``)\n    or from a saved snapshot (``HopfieldStore.load(path, domain=...)``). Use\n    :meth:`query` from operators that need a warm-start prior, :meth:`write`\n    from :func:`pce.operators.vimarsa.consolidate`, and :meth:`persist` from\n    benchmark drivers that want cross-prompt continuity within a domain.\n\n    Persistence format: ``audit/storehouse/<domain>.npz`` with keys\n    ``patterns`` (float32 (N, D)), ``aspect_labels`` (object array length N),\n    and ``meta`` (json-encoded dict with ``beta``, ``capacity``).\n    \"\"\"\n\n    def __init__(\n        self,\n        *,\n        domain: str,\n        beta: float = 8.0,\n        capacity: int = 256,\n        sws_replace_threshold: float = 0.92,\n    ) -> None:\n        if not domain:\n            raise ValueError(\"HopfieldStore: domain must be a non-empty string\")\n        if beta <= 0:\n            raise ValueError(f\"HopfieldStore: beta must be > 0, got {beta}\")\n        if capacity <= 0:\n            raise ValueError(f\"HopfieldStore: capacity must be > 0, got {capacity}\")\n        if not 0.0 < sws_replace_threshold <= 1.0:\n            raise ValueError(\n                \"HopfieldStore: sws_replace_threshold must be in (0, 1], \"\n                f\"got {sws_replace_threshold}\"\n            )\n        self.domain = str(domain)\n        self.beta = float(beta)\n        self.capacity = int(capacity)\n        self.sws_replace_threshold = float(sws_replace_threshold)\n        self._patterns: EmbeddingArray = np.zeros((0, 0), dtype=np.float32)\n        self._labels: list[str] = []\n\n    @property\n    def n_patterns(self) -> int:\n        return int(self._patterns.shape[0])\n\n    @property\n    def dim(self) -> int:\n        return int(self._patterns.shape[1]) if self._patterns.size else 0\n\n    def query(\n        self,\n        query_vec: npt.NDArray[np.float32],\n        *,\n        aspect_labels: list[str] | None = None,\n    ) -> HopfieldQueryResult:\n        \"\"\"Softmax-attend over stored patterns.\n\n        ``aspect_labels`` is the ordered list of aspect names whose per-aspect\n        mass should be returned in :attr:`HopfieldQueryResult.aspect_priors`.\n        Each entry sums the softmax mass of every stored pattern whose label\n        equals that aspect.\n        \"\"\"\n        q = _l2_normalize(np.asarray(query_vec, dtype=np.float32).reshape(-1))\n        labels = list(aspect_labels or [])\n        if self.n_patterns == 0:\n            return HopfieldQueryResult(\n                n_patterns=0,\n                energy=float(\"inf\"),\n                attention=np.zeros((0,), dtype=np.float32),\n                retrieved=q.copy(),\n                aspect_priors=np.zeros((len(labels),), dtype=np.float32),\n            )\n        scores = self._patterns @ q  # (N,)\n        # Energy = -1/beta * logsumexp(beta * scores) (Ramsauer 2020 eq. 1).\n        m = float(np.max(scores))\n        lse = float(m + np.log(np.exp(self.beta * (scores - m)).sum() + 1e-30) / 1.0)\n        energy = -lse / self.beta\n        # Softmax attention.\n        att_logits = self.beta * scores\n        att_logits -= float(att_logits.max())\n        att = np.exp(att_logits, dtype=np.float64)\n        att /= att.sum() + 1e-30\n        att32 = att.astype(np.float32)\n        retrieved = (att32 @ self._patterns).astype(np.float32)\n        if labels:\n            priors = np.zeros((len(labels),), dtype=np.float32)\n            for i, lab in enumerate(labels):\n                mass = float(sum(float(att32[j]) for j, p in enumerate(self._labels) if p == lab))\n                priors[i] = mass\n        else:\n            priors = np.zeros((0,), dtype=np.float32)\n        return HopfieldQueryResult(\n            n_patterns=self.n_patterns,\n            energy=float(energy),\n            attention=att32,\n            retrieved=retrieved,\n            aspect_priors=priors,\n        )\n\n    def write(\n        self,\n        embedding: npt.NDArray[np.float32],\n        *,\n        label: str,\n        mode: WriteMode = \"rem\",\n    ) -> None:\n        \"\"\"Add (REM) or consolidate (SWS) one pattern.\n\n        REM appends. SWS finds the nearest stored pattern by cosine and, if\n        cosine ≥ ``sws_replace_threshold``, averages with it instead of\n        appending; below the threshold it falls through to REM. Capacity is\n        enforced FIFO: if writing would exceed capacity the oldest pattern\n        is dropped.\n        \"\"\"\n        if mode not in (\"rem\", \"sws\"):\n            raise ValueError(f\"HopfieldStore.write: unknown mode={mode!r}\")\n        emb = _l2_normalize(np.asarray(embedding, dtype=np.float32).reshape(-1))\n        if self.dim and emb.shape[0] != self.dim:\n            raise ValueError(\n                f\"HopfieldStore.write: embedding dim {emb.shape[0]} != store dim {self.dim}\"\n            )\n        if self.n_patterns == 0:\n            self._patterns = emb[None, :].copy()\n            self._labels = [str(label)]\n            return\n        if mode == \"sws\":\n            sims = self._patterns @ emb\n            j_best = int(np.argmax(sims))\n            if float(sims[j_best]) >= self.sws_replace_threshold:\n                merged = _l2_normalize(0.5 * (self._patterns[j_best] + emb))\n                self._patterns[j_best] = merged\n                # Keep the existing label (slow consolidation does not relabel).\n                return\n        # REM (or SWS fall-through): append, drop oldest if at capacity.\n        if self.n_patterns >= self.capacity:\n            self._patterns = self._patterns[1:]\n            self._labels = self._labels[1:]\n        self._patterns = np.vstack([self._patterns, emb[None, :]]).astype(np.float32)\n        self._labels.append(str(label))\n\n    def persist(self, root: Path | str = Path(\"audit/storehouse\")) -> Path:\n        \"\"\"Write the matrix + labels + meta to ``root/<domain>.npz``.\"\"\"\n        root_p = Path(root)\n        root_p.mkdir(parents=True, exist_ok=True)\n        out = root_p / f\"{self.domain}.npz\"\n        np.savez(\n            out,\n            patterns=self._patterns,\n            aspect_labels=np.array(self._labels, dtype=object),\n            meta=np.array({\"beta\": self.beta, \"capacity\": self.capacity}, dtype=object),\n        )\n        return out\n\n    @classmethod\n    def load(cls, path: Path | str, *, domain: str | None = None) -> HopfieldStore:\n        \"\"\"Restore a store from a snapshot written by :meth:`persist`.\"\"\"\n        p = Path(path)\n        if not p.exists():\n            raise FileNotFoundError(f\"HopfieldStore.load: {p} does not exist\")\n        with np.load(p, allow_pickle=True) as data:\n            patterns = np.asarray(data[\"patterns\"], dtype=np.float32)\n            labels = [str(x) for x in data[\"aspect_labels\"].tolist()]\n            meta_obj = data[\"meta\"].item()\n        beta = float(meta_obj.get(\"beta\", 8.0)) if isinstance(meta_obj, dict) else 8.0\n        capacity = int(meta_obj.get(\"capacity\", 256)) if isinstance(meta_obj, dict) else 256\n        store = cls(domain=str(domain or p.stem), beta=beta, capacity=capacity)\n        store._patterns = patterns\n        store._labels = labels\n        return store\n\n    def reset(self) -> None:\n        \"\"\"Clear all stored patterns. Used between domains in the benchmark.\"\"\"\n        self._patterns = np.zeros((0, 0), dtype=np.float32)\n        self._labels = []\n",
 "pce-poem/pce/cascade.py": "\"\"\"End-to-end Pratyabhijñā cascade orchestrator.\n\n``run_cascade(prompt, constraint, ...)`` executes the full\n``cit -> icchā -> apohana -> jñāna -> kriyā -> vimarśa -> kriyā(revision)``\npipeline and returns a :class:`CascadeState` capturing every intermediate.\n\nv0.3 (ADR-002 / ADR-003 / ADR-004 / ADR-005) makes the cascade a real\ninference loop:\n\n1. **Always** run the draft pass (P1): ``iccha -> apohana -> jnana -> kriya``.\n2. **Always** run vimarsa with ``return_brief=True`` and feed\n   ``delta_F_draft`` as the ΔF evidence; vimarsa's event additionally requires\n   ``delta_F >= delta_F_threshold`` (default 0.05).\n3. **Always** run the shadow revision pass (P2) when ``commit_policy`` is\n   ``\"event_gated\"`` or ``\"always_revise\"``, regardless of whether vimarsa\n   fired -- so H8 (revision-vs-draft contribution) is *always* measurable\n   on every paired item.\n4. **Commit** according to ``commit_policy``:\n\n   * ``\"event_gated\"`` (v0.3 default): commit revision iff vimarsa fired,\n     otherwise commit draft.\n   * ``\"always_revise\"`` (v0.2 behaviour): commit revision unconditionally.\n   * ``\"always_draft\"`` (explicit ablation, formerly ``bypass_vimarsa=True``):\n     commit draft unconditionally; revision pass is skipped to save cost.\n\n   ``state.committed`` records ``\"revision\"`` or ``\"draft\"``; the audit\n   records ``commit_policy``, ``vimarsa_event``, ``delta_F_draft``,\n   ``revision_differs_from_draft``, and the per-item free-energy ledger.\n\nPer ADR-005 ``iccha`` is invoked with ``prompt_mode=\"verbatim\"`` and\n``sampler_grid_mode=\"parity\"`` so the bare-vs-cascade contrast is purely\narchitectural rather than confounded by prompt or sampler drift. Per\nADR-002 ``apohana`` is invoked with ``normalize=True`` so ``jnana`` sees\nthe shifted apoha that lets must-avoid penalties affect the posterior. Per\nADR-003 ``jnana`` runs in ``aspect_conditioned`` mode whenever the caller\nsupplies aspects, so the BMR posterior reflects which candidates actually\nrealize the must-have aspects. Per ADR-004 the cascade can thread an\noptional :class:`pce.active_inference.HopfieldStore` so apohana gets a\nwarm-start prior and vimarsa.consolidate writes the committed surface\nback at the end.\n\nThe substrate is :class:`pce.substrate.lm_protocol.LMProtocol` so the\ncascade can run against either ``LocalLM`` (Qwen2-1.5B) or ``HaikuLM``\n(Anthropic Haiku via ``claude`` CLI). Both substrates honor ``seed`` so\ncandidate diversity in parity mode is purely seed-driven.\n\"\"\"\nfrom __future__ import annotations\n\nimport time\nfrom collections.abc import Callable\nfrom typing import Literal\n\nimport numpy as np\nimport numpy.typing as npt\n\nfrom pce.active_inference.budget import FreeEnergyBudget\nfrom pce.active_inference.hopfield import HopfieldStore\nfrom pce.operators.ananda import ananda\nfrom pce.operators.apohana import apohana\nfrom pce.operators.iccha import iccha\nfrom pce.operators.jnana import jnana\nfrom pce.operators.kriya import kriya\nfrom pce.operators.vimarsa import (\n    DEFAULT_ASPECT_COSINE_HIT,\n    DEFAULT_DELTA_F_THRESHOLD,\n    consolidate,\n    vimarsa,\n)\nfrom pce.policies import (\n    CommitPolicy as CommitPolicyBase,\n)\nfrom pce.policies import (\n    LearnedGate,\n    PolicyFeatures,\n    policy_for_name,\n)\nfrom pce.substrate.embed import Embedder\nfrom pce.substrate.lm import LocalLM\nfrom pce.substrate.lm_protocol import LMProtocol\nfrom pce.types import Candidate, CascadeState, Constraint\n\n# Per-pass seed offset so the revision pass draws from a distinct sampler\n# subspace from the draft pass while still being deterministic from\n# ``base_seed``.\n_REVISION_SEED_OFFSET = 17\n\n# v0.4 (ADR-002): commit-policy literal expanded with ``learned_gate``.\n# ``oracle`` is intentionally NOT in the cascade-time literal — it is a\n# post-hoc analysis policy that requires both surfaces' scores, which the\n# cascade cannot produce on its own.\nCommitPolicy = Literal[\n    \"event_gated\", \"always_revise\", \"always_draft\", \"learned_gate\"\n]\n\n\ndef _entropy_of(scores: np.ndarray) -> float:  # type: ignore[type-arg]\n    arr = np.asarray(scores, dtype=np.float64)\n    if arr.size == 0:\n        return 0.0\n    arr = arr - arr.max()\n    p = np.exp(arr)\n    p /= p.sum() + 1e-30\n    p = np.clip(p, 1e-30, 1.0)\n    return float(-np.sum(p * np.log(p)))\n\n\ndef _per_candidate_apoha_iccha_trajectory(\n    apoha: npt.NDArray[np.float32],\n    ananda: npt.NDArray[np.float32],\n) -> list[tuple[float, float]]:\n    \"\"\"v0.4 (FR-4.v4 / ADR-005 in PRD): per-candidate (e_iccha, e_apoha) trajectory.\n\n    `vimarsa.switching_ok` was always trivially True in v0.3 because the\n    cascade passed `iccha_apoha_trajectory=None`. v0.4 supplies a real\n    trajectory: each candidate contributes one point\n    ``(softplus(ananda_i), softplus(apoha_i))``. The trajectory has length K\n    so vimarsa's switching gate is exercised on the same evidence the\n    cascade just consumed.\n\n    Using softplus rather than raw scores keeps both axes positive (so the\n    ratio test in :func:`vimarsa._count_switching` is well-defined) without\n    losing relative ordering between candidates.\n    \"\"\"\n    a = np.asarray(ananda, dtype=np.float64)\n    b = np.asarray(apoha, dtype=np.float64)\n    n = int(min(a.size, b.size))\n    out: list[tuple[float, float]] = []\n    for i in range(n):\n        e_i = float(np.log1p(np.exp(np.clip(a[i], -50.0, 50.0))))\n        e_a = float(np.log1p(np.exp(np.clip(b[i], -50.0, 50.0))))\n        out.append((e_i, e_a))\n    return out\n\n\ndef _aspect_membership_matrix(\n    candidates: tuple[Candidate, ...],\n    aspects: list[str],\n    *,\n    embed: Embedder,\n) -> npt.NDArray[np.float32]:\n    \"\"\"Cosine matrix between K candidate embeddings and A aspect embeddings.\"\"\"\n    if not aspects:\n        return np.zeros((len(candidates), 0), dtype=np.float32)\n    asp_embs = embed.encode(list(aspects))\n    if asp_embs.ndim == 1:\n        asp_embs = asp_embs[None, :]\n    cand_emb = np.stack([c.embedding for c in candidates], axis=0).astype(np.float32)\n    return (cand_emb @ asp_embs.T).astype(np.float32)\n\n\ndef _one_pass(\n    *,\n    prompt: str,\n    constraint: Constraint,\n    lm: LMProtocol,\n    embed: Embedder,\n    K: int,\n    max_tokens: int,\n    base_seed: int,\n    render_mode: str,\n    polish_lm: LocalLM | None,\n    claude_renderer: Callable[[str], str] | None,\n    lambda_a: float,\n    lambda_p: float,\n    cit_temperature: float,\n    aspects: list[str],\n    aspect_priors: npt.NDArray[np.float32] | None,\n    hopfield: HopfieldStore | None,\n    hopfield_weight: float,\n) -> tuple[\n    tuple[Candidate, ...],\n    npt.NDArray[np.float32],\n    npt.NDArray[np.float32],\n    int,\n    float,\n    npt.NDArray[np.float32],\n    str,\n    npt.NDArray[np.float32],\n]:\n    \"\"\"Run one cascade pass; returns (cands, apoha, ananda, sel, dF, post, surface, aspect_mem).\"\"\"\n    candidates = iccha(\n        prompt,\n        constraint,\n        lm=lm,\n        K=K,\n        base_seed=base_seed,\n        max_tokens=max_tokens,\n        prompt_mode=\"verbatim\",\n        sampler_grid_mode=\"parity\",\n        cit_temperature=cit_temperature,\n    )\n    apoha = apohana(\n        candidates,\n        constraint,\n        embed=embed,\n        normalize=True,\n        hopfield=hopfield,\n        hopfield_weight=hopfield_weight,\n    )\n    ananda_scores = np.array(\n        [ananda(c, constraint=constraint, embed=embed) for c in candidates],\n        dtype=np.float32,\n    )\n    aspect_membership = _aspect_membership_matrix(candidates, aspects, embed=embed)\n    if aspects:\n        sel_idx, delta_F, posterior = jnana(\n            candidates,\n            apoha,\n            ananda_scores,\n            reduction_target=\"aspect_conditioned\",\n            aspect_membership=aspect_membership,\n            aspect_priors=aspect_priors,\n            lambda_a=lambda_a,\n            lambda_p=lambda_p,\n        )\n    else:\n        sel_idx, delta_F, posterior = jnana(\n            candidates, apoha, ananda_scores, lambda_a=lambda_a, lambda_p=lambda_p\n        )\n    selected = candidates[sel_idx]\n    surface = kriya(\n        selected,\n        render_mode=render_mode,  # type: ignore[arg-type]\n        lm=polish_lm if render_mode == \"polish\" else None,\n        embed=embed if render_mode == \"polish\" else None,\n        claude_renderer=claude_renderer,\n    )\n    return (\n        candidates,\n        apoha,\n        ananda_scores,\n        sel_idx,\n        delta_F,\n        posterior,\n        surface,\n        aspect_membership,\n    )\n\n\ndef _resolve_commit_policy(\n    commit_policy: CommitPolicy | None, bypass_vimarsa: bool\n) -> CommitPolicy:\n    \"\"\"Resolve the v0.3 ``commit_policy`` from kwargs.\n\n    ``bypass_vimarsa=True`` is the v0.2 deprecated alias for\n    ``commit_policy=\"always_draft\"``; if both are set with conflicting\n    values we raise so the caller resolves the ambiguity rather than\n    silently picking one.\n    \"\"\"\n    if commit_policy is None:\n        return \"always_draft\" if bypass_vimarsa else \"event_gated\"\n    if bypass_vimarsa and commit_policy != \"always_draft\":\n        raise ValueError(\n            f\"run_cascade: bypass_vimarsa=True conflicts with commit_policy={commit_policy!r}; \"\n            \"drop bypass_vimarsa or set commit_policy='always_draft'\"\n        )\n    return commit_policy\n\n\ndef run_cascade(\n    prompt: str,\n    constraint: Constraint,\n    *,\n    lm: LMProtocol,\n    embed: Embedder,\n    K: int = 4,\n    cit_temperature: float = 1.0,\n    max_tokens: int = 200,\n    base_seed: int = 0,\n    retrieval_set: list[str] | None = None,\n    aspects: list[str] | None = None,\n    render_mode: str = \"verbatim\",\n    claude_renderer: Callable[[str], str] | None = None,\n    lambda_a: float = 2.0,\n    lambda_p: float = 2.0,\n    bypass_vimarsa: bool = False,\n    commit_policy: CommitPolicy | None = None,\n    delta_F_threshold: float = DEFAULT_DELTA_F_THRESHOLD,\n    aspect_cosine_hit: float = DEFAULT_ASPECT_COSINE_HIT,\n    polish_lm: LocalLM | None = None,\n    hopfield: HopfieldStore | None = None,\n    hopfield_weight: float = 0.25,\n    budget: FreeEnergyBudget | None = None,\n    brief_override: str | None = None,\n) -> CascadeState:\n    \"\"\"Run the v0.3 event-gated, always-shadow-revision cascade on one prompt.\n\n    ``commit_policy``:\n\n    * ``\"event_gated\"`` (default): commit revision iff vimarsa fires;\n      otherwise commit draft. Always runs both passes so H8 is measurable.\n    * ``\"always_revise\"`` (v0.2 behaviour): commit revision unconditionally.\n    * ``\"always_draft\"``: skip the revision pass; commit draft. Equivalent\n      to the v0.2 ``bypass_vimarsa=True`` ablation.\n\n    ``brief_override``: when set, replaces the vimarsa-generated revision\n    brief with this fixed string. This is the lever the\n    ``haiku_generic_revise_2pass`` benchmark control arm uses to isolate\n    the *content* of the brief from the *existence* of a revision pass.\n    Default ``None`` -> use the vimarsa brief.\n\n    ``bypass_vimarsa=True`` is kept as a deprecated alias for\n    ``commit_policy=\"always_draft\"`` so the v0.2 prove-gate scripts and\n    benchmark drivers keep working until they are migrated.\n    \"\"\"\n    if not prompt.strip():\n        raise ValueError(\"run_cascade: prompt must be non-empty\")\n    policy = _resolve_commit_policy(commit_policy, bypass_vimarsa)\n    t0 = time.time()\n    aspects_list = list(aspects or [])\n    retrieval_list = list(retrieval_set or [])\n    ledger = budget if budget is not None else FreeEnergyBudget()\n\n    # Per-aspect prior from the storehouse, when available. Falls back to\n    # uniform when the store is empty or no aspects are supplied.\n    aspect_priors: npt.NDArray[np.float32] | None = None\n    storehouse_aspect_attention: list[float] = []\n    if hopfield is not None and aspects_list and hopfield.n_patterns > 0:\n        # Query the storehouse with the constraint embedding to get a\n        # per-aspect mass vector.\n        res = hopfield.query(constraint.embedding, aspect_labels=aspects_list)\n        storehouse_aspect_attention = [float(p) for p in res.aspect_priors.tolist()]\n        if float(res.aspect_priors.sum()) > 0.0:\n            aspect_priors = res.aspect_priors\n\n    # ---- Pass 1: draft ---------------------------------------------------\n    cands_d, apoha_d, anan_d, sel_d, dF_d, post_d, draft, asp_mem_d = _one_pass(\n        prompt=prompt,\n        constraint=constraint,\n        lm=lm,\n        embed=embed,\n        K=K,\n        max_tokens=max_tokens,\n        base_seed=base_seed,\n        render_mode=render_mode,\n        polish_lm=polish_lm,\n        claude_renderer=claude_renderer,\n        lambda_a=lambda_a,\n        lambda_p=lambda_p,\n        cit_temperature=cit_temperature,\n        aspects=aspects_list,\n        aspect_priors=aspect_priors,\n        hopfield=hopfield,\n        hopfield_weight=hopfield_weight,\n    )\n    e_iccha_d = _entropy_of(anan_d)\n    e_apoha_d = _entropy_of(apoha_d)\n    ledger.earn_jnana(dF_d, note=\"draft pass\")\n    ledger.earn_tokens(len(cands_d[sel_d].text.split()), note=\"draft tokens\")\n\n    # ---- vimarsa (always run; ΔF-gated event) ---------------------------\n    # v0.4 (FR-4.v4): supply a real per-candidate trajectory so vimarsa's\n    # switching gate is exercised. v0.3 always passed None, which made\n    # ``switching_ok`` trivially True for every cascade item.\n    apoha_iccha_trajectory_d = _per_candidate_apoha_iccha_trajectory(apoha_d, anan_d)\n    vim_out_d = vimarsa(\n        prompt,\n        draft,\n        embed=embed,\n        retrieval_set=retrieval_list,\n        aspects=aspects_list,\n        ananda_score=float(anan_d[sel_d]),\n        iccha_apoha_trajectory=apoha_iccha_trajectory_d,\n        delta_F=float(dF_d),\n        delta_F_threshold=float(delta_F_threshold),\n        aspect_cosine_hit=float(aspect_cosine_hit),\n        return_brief=True,\n    )\n    assert len(vim_out_d) == 4\n    event_d, novelty_d, diag_d, brief = vim_out_d\n\n    # Aspect cost: 1 - max aspect cosine on the draft (closer = cheaper).\n    if aspects_list and asp_mem_d.size:\n        max_asp = float(asp_mem_d[sel_d].max())\n        ledger.earn_aspect(max(0.0, 1.0 - max_asp), note=\"draft aspect distance\")\n\n    # ---- v0.4 (ADR-003): FE budget hard gate before shadow revision pass.\n    # The cascade still always commits the draft when the budget is\n    # underwater; ``commit_policy`` never overrides a budget abort. The two\n    # tier hierarchy is:\n    #     1. budget gate (generation-level) -> generate revision at all?\n    #     2. commit policy (selection-level) -> commit revision over draft?\n    fe_budget_underwater = not ledger.should_continue_revision()\n\n    def _draft_only_state(reason: str) -> CascadeState:\n        return CascadeState(\n            prompt=prompt,\n            constraint=constraint,\n            cit_temperature=float(cit_temperature),\n            candidates=cands_d,\n            posterior=post_d,\n            selected=cands_d[sel_d],\n            surface=draft,\n            vimarsa_event=bool(event_d),\n            vimarsa_novelty=float(novelty_d),\n            aspects=tuple(aspects_list),\n            surface_draft=draft,\n            surface_revision=None,\n            vimarsa_event_draft=bool(event_d),\n            vimarsa_brief=brief,\n            committed=\"draft\",\n            commit_policy=policy,\n            audit={\n                \"elapsed_s\": float(time.time() - t0),\n                \"delta_F_draft\": float(dF_d),\n                \"delta_F\": float(dF_d),\n                \"selected_idx_draft\": int(sel_d),\n                \"selected_idx\": int(sel_d),\n                \"ananda_scores_draft\": [float(s) for s in anan_d.tolist()],\n                \"ananda_scores\": [float(s) for s in anan_d.tolist()],\n                \"apoha_scores_draft\": [float(s) for s in apoha_d.tolist()],\n                \"apoha_scores\": [float(s) for s in apoha_d.tolist()],\n                \"vimarsa_diag_draft\": diag_d,\n                \"vimarsa_diag\": diag_d,\n                \"entropy_iccha_draft\": e_iccha_d,\n                \"entropy_apoha_draft\": e_apoha_d,\n                \"two_pass\": False,\n                \"bypassed\": reason == \"commit_policy=always_draft\",\n                \"revision_skipped\": True,\n                \"revision_skipped_reason\": reason,\n                \"fe_budget_underwater\": bool(fe_budget_underwater),\n                \"budget_ledger\": ledger.to_audit(),\n                \"policy_features\": PolicyFeatures(\n                    delta_F=float(dF_d),\n                    novelty=float(novelty_d),\n                    aspect_count=float(\n                        diag_d.get(\"aspect_count\", 0.0) if isinstance(diag_d, dict) else 0.0\n                    ),\n                    ananda=float(anan_d[sel_d]),\n                    budget_balance=float(ledger.balance()),\n                ).to_audit(),\n                \"learned_gate\": None,\n                \"storehouse_aspect_attention\": storehouse_aspect_attention,\n                \"n_storehouse_patterns\": int(hopfield.n_patterns) if hopfield else 0,\n            },\n        )\n\n    if policy == \"always_draft\":\n        return _draft_only_state(\"commit_policy=always_draft\")\n    if fe_budget_underwater:\n        return _draft_only_state(\"fe_budget_underwater\")\n\n    effective_brief = brief_override if brief_override is not None else brief\n    revision_prompt = (\n        f\"{prompt.rstrip()}\\n\\n\"\n        f\"Reviser brief: {effective_brief}\\n\\n\"\n        f\"Previous draft:\\n{draft.strip()}\\n\\n\"\n        \"Now produce the revised response.\"\n    )\n    cands_r, apoha_r, anan_r, sel_r, dF_r, post_r, revision, asp_mem_r = _one_pass(\n        prompt=revision_prompt,\n        constraint=constraint,\n        lm=lm,\n        embed=embed,\n        K=K,\n        max_tokens=max_tokens,\n        base_seed=base_seed + _REVISION_SEED_OFFSET,\n        render_mode=render_mode,\n        polish_lm=polish_lm,\n        claude_renderer=claude_renderer,\n        lambda_a=lambda_a,\n        lambda_p=lambda_p,\n        cit_temperature=cit_temperature,\n        aspects=aspects_list,\n        aspect_priors=aspect_priors,\n        hopfield=hopfield,\n        hopfield_weight=hopfield_weight,\n    )\n    e_iccha_r = _entropy_of(anan_r)\n    e_apoha_r = _entropy_of(apoha_r)\n    ledger.earn_jnana(dF_r, note=\"revision pass\")\n    ledger.earn_tokens(len(cands_r[sel_r].text.split()), note=\"revision tokens\")\n    if aspects_list and asp_mem_r.size:\n        max_asp_r = float(asp_mem_r[sel_r].max())\n        ledger.earn_aspect(max(0.0, 1.0 - max_asp_r), note=\"revision aspect distance\")\n\n    apoha_iccha_trajectory_r = _per_candidate_apoha_iccha_trajectory(apoha_r, anan_r)\n    vim_out_r = vimarsa(\n        prompt,\n        revision,\n        embed=embed,\n        retrieval_set=retrieval_list,\n        aspects=aspects_list,\n        ananda_score=float(anan_r[sel_r]),\n        iccha_apoha_trajectory=apoha_iccha_trajectory_r,\n        delta_F=float(dF_r),\n        delta_F_threshold=float(delta_F_threshold),\n        aspect_cosine_hit=float(aspect_cosine_hit),\n        return_brief=False,\n    )\n    assert len(vim_out_r) == 3\n    event_r, novelty_r, diag_r = vim_out_r\n\n    # ---- Commit policy (v0.4 ADR-002) ----------------------------------\n    # Build features once from the draft-pass audit. The features dict here\n    # is a v0.4 audit shape that ``extract_features_from_audit`` knows how\n    # to read; supplying it directly is cheaper than re-building the dict.\n    diag_d_safe = diag_d if isinstance(diag_d, dict) else {}\n    policy_features = PolicyFeatures(\n        delta_F=float(dF_d),\n        novelty=float(novelty_d),\n        aspect_count=float(diag_d_safe.get(\"aspect_count\", 0.0)),\n        ananda=float(anan_d[sel_d]),\n        budget_balance=float(ledger.balance()),\n    )\n    learned_gate_audit: dict[str, object] | None = None\n    if policy == \"always_revise\":\n        committed = \"revision\"\n    elif policy == \"event_gated\":\n        committed = \"revision\" if bool(event_d) else \"draft\"\n    elif policy == \"learned_gate\":\n        gate: CommitPolicyBase = policy_for_name(\"learned_gate\")\n        decision = gate.decide(policy_features, vimarsa_event=bool(event_d))\n        committed = \"revision\" if decision else \"draft\"\n        if isinstance(gate, LearnedGate):\n            learned_gate_audit = gate.to_audit()\n    else:  # always_draft handled above; keep mypy exhaustive\n        raise ValueError(f\"run_cascade: unreachable commit_policy={policy!r}\")\n    final_surface = revision if committed == \"revision\" else draft\n\n    # ---- Storehouse consolidation ---------------------------------------\n    consolidate_audit: dict[str, object] | None = None\n    if hopfield is not None:\n        consolidate_audit = consolidate(\n            surface=final_surface,\n            aspects=aspects_list,\n            embed=embed,\n            hopfield=hopfield,\n            mode=\"rem\",\n        )\n\n    selected_for_state = cands_r[sel_r] if committed == \"revision\" else cands_d[sel_d]\n    posterior_for_state = post_r if committed == \"revision\" else post_d\n    candidates_for_state = cands_r if committed == \"revision\" else cands_d\n    state = CascadeState(\n        prompt=prompt,\n        constraint=constraint,\n        cit_temperature=float(cit_temperature),\n        candidates=candidates_for_state,\n        posterior=posterior_for_state,\n        selected=selected_for_state,\n        surface=final_surface,\n        vimarsa_event=bool(event_d),  # event from draft drives the commit decision\n        vimarsa_novelty=float(novelty_r),\n        aspects=tuple(aspects_list),\n        surface_draft=draft,\n        surface_revision=revision,\n        vimarsa_event_draft=bool(event_d),\n        vimarsa_brief=brief,\n        committed=committed,\n        commit_policy=policy,\n        audit={\n            \"elapsed_s\": float(time.time() - t0),\n            \"two_pass\": True,\n            \"bypassed\": False,\n            \"revision_skipped\": False,\n            \"delta_F_draft\": float(dF_d),\n            \"delta_F_revision\": float(dF_r),\n            \"delta_F\": float(dF_r if committed == \"revision\" else dF_d),\n            \"selected_idx_draft\": int(sel_d),\n            \"selected_idx_revision\": int(sel_r),\n            \"selected_idx\": int(sel_r if committed == \"revision\" else sel_d),\n            \"ananda_scores_draft\": [float(s) for s in anan_d.tolist()],\n            \"ananda_scores_revision\": [float(s) for s in anan_r.tolist()],\n            \"ananda_scores\": [\n                float(s) for s in (anan_r if committed == \"revision\" else anan_d).tolist()\n            ],\n            \"apoha_scores_draft\": [float(s) for s in apoha_d.tolist()],\n            \"apoha_scores_revision\": [float(s) for s in apoha_r.tolist()],\n            \"apoha_scores\": [\n                float(s) for s in (apoha_r if committed == \"revision\" else apoha_d).tolist()\n            ],\n            \"vimarsa_diag_draft\": diag_d,\n            \"vimarsa_diag_revision\": diag_r,\n            \"vimarsa_diag\": diag_r if committed == \"revision\" else diag_d,\n            \"vimarsa_brief\": brief,\n            \"vimarsa_brief_effective\": effective_brief,\n            \"brief_override_used\": bool(brief_override is not None),\n            \"vimarsa_event_draft\": bool(event_d),\n            \"vimarsa_event_revision\": bool(event_r),\n            \"entropy_iccha_draft\": e_iccha_d,\n            \"entropy_apoha_draft\": e_apoha_d,\n            \"entropy_iccha\": e_iccha_r,\n            \"entropy_apoha\": e_apoha_r,\n            \"revision_differs_from_draft\": bool(revision.strip() != draft.strip()),\n            \"delta_F_threshold\": float(delta_F_threshold),\n            \"fe_budget_underwater\": False,\n            \"budget_ledger\": ledger.to_audit(),\n            \"policy_features\": policy_features.to_audit(),\n            \"learned_gate\": learned_gate_audit,\n            \"storehouse_aspect_attention\": storehouse_aspect_attention,\n            \"n_storehouse_patterns\": int(hopfield.n_patterns) if hopfield else 0,\n            \"storehouse_consolidate\": consolidate_audit,\n        },\n    )\n    return state\n",
 "pce-poem/pce/consolidation/__init__.py": "\"\"\"Sleep / consolidation routines for the Hopfield storehouse.\"\"\"\nfrom pce.consolidation.sleep import (\n    is_consolidated,\n    run_rem,\n    run_sleep_cycle,\n    run_sws,\n)\n\n__all__ = [\"is_consolidated\", \"run_rem\", \"run_sleep_cycle\", \"run_sws\"]\n",
 "pce-poem/pce/consolidation/sleep.py": "\"\"\"SWS / REM consolidation cycles for the Hopfield store.\n\n`run_sws` performs the deep-sleep abstraction step (k-means over recent traces).\n`run_rem` performs the REM Metropolis replay step. Together they produce a\npost-consolidation HopfieldStore whose patterns include both the originals and\nthe abstracted/replayed centroids.\n\nBackground: see [docs/research-extended.md §6](../../../docs/research-extended.md#6-sleepconsolidation-loops).\n\"\"\"\nfrom __future__ import annotations\n\nimport numpy as np\nimport numpy.typing as npt\n\nfrom pce.substrate.hopfield import HopfieldStore\n\n\ndef run_sws(\n    store: HopfieldStore,\n    traces: list[npt.NDArray[np.float32]],\n    *,\n    n_centroids: int = 4,\n    n_iter: int = 25,\n    seed: int = 0,\n) -> list[npt.NDArray[np.float32]]:\n    \"\"\"Slow-wave consolidation: cluster recent traces, store centroids.\"\"\"\n    return store.consolidate_sws(traces, n_centroids=n_centroids, n_iter=n_iter, seed=seed)\n\n\ndef run_rem(\n    store: HopfieldStore,\n    *,\n    n_steps: int = 100,\n    temperature: float = 1.5,\n    seed: int = 0,\n) -> list[npt.NDArray[np.float32]]:\n    \"\"\"REM consolidation: stochastic recall trajectory at higher temperature.\"\"\"\n    return store.consolidate_rem(n_steps=n_steps, temperature=temperature, seed=seed)\n\n\ndef run_sleep_cycle(\n    store: HopfieldStore,\n    traces: list[npt.NDArray[np.float32]],\n    *,\n    sws_centroids: int = 4,\n    sws_iter: int = 25,\n    rem_steps: int = 100,\n    rem_temperature: float = 1.5,\n    seed: int = 0,\n) -> dict[str, int]:\n    \"\"\"Run one SWS pass, then one REM pass. Return diagnostics.\"\"\"\n    n_before = store.n_patterns\n    centroids = run_sws(store, traces, n_centroids=sws_centroids, n_iter=sws_iter, seed=seed)\n    rem_traj = run_rem(store, n_steps=rem_steps, temperature=rem_temperature, seed=seed + 1)\n    return {\n        \"n_patterns_before\": int(n_before),\n        \"n_patterns_after\": int(store.n_patterns),\n        \"n_sws_centroids\": int(len(centroids)),\n        \"n_rem_steps\": int(len(rem_traj)),\n    }\n\n\ndef is_consolidated(\n    store: HopfieldStore,\n    pattern: npt.NDArray[np.float32],\n    *,\n    threshold: float = 0.92,\n) -> bool:\n    \"\"\"Probe: does `pattern` recall to itself in the store?\"\"\"\n    if store.n_patterns == 0:\n        return False\n    recalled = store.recall(pattern)\n    rec_norm = recalled / (np.linalg.norm(recalled) + 1e-12)\n    pat_norm = pattern / (np.linalg.norm(pattern) + 1e-12)\n    return float(np.dot(rec_norm, pat_norm)) >= float(threshold)\n",
 "pce-poem/pce/operators/__init__.py": "\"\"\"Pratyabhijñā operators (cit, ananda, iccha, apohana, jnana, kriya, vimarsa).\"\"\"\nfrom pce.operators.ananda import ananda\nfrom pce.operators.apohana import apohana\nfrom pce.operators.cit import cit\nfrom pce.operators.iccha import iccha\nfrom pce.operators.jnana import jnana\nfrom pce.operators.kriya import kriya\nfrom pce.operators.vimarsa import consolidate, vimarsa\n\n__all__ = [\n    \"ananda\",\n    \"apohana\",\n    \"cit\",\n    \"consolidate\",\n    \"iccha\",\n    \"jnana\",\n    \"kriya\",\n    \"vimarsa\",\n]\n",
 "pce-poem/pce/operators/ananda.py": "\"\"\"`ananda` - aesthetic-coherence reward.\n\nReturns a scalar in [0, 1] aggregating coherence (cosine to constraint),\ndiversity (distinct-2/3 tokens), form fidelity (regex / syllable / required-\ntoken check), and an optional cross-encoder reward.\n\nDefaults follow [docs/operator-spec.md §2](../../../docs/operator-spec.md#2-ananda--aesthetic-coherence-scorer).\n\"\"\"\nfrom __future__ import annotations\n\nimport re\n\nfrom pce.substrate.embed import Embedder\nfrom pce.types import Candidate, Constraint\n\nDEFAULT_WEIGHTS = {\n    \"coherence\": 0.40,\n    \"diversity\": 0.20,\n    \"form_fidelity\": 0.20,\n    \"reward_model\": 0.20,\n}\n\n_SYLL_RE = re.compile(r\"[aeiouy]+\", re.IGNORECASE)\n\n\ndef _count_syllables(text: str) -> int:\n    return len(_SYLL_RE.findall(text))\n\n\ndef _distinct_n(tokens: list[str], n: int) -> float:\n    if len(tokens) < n:\n        return 0.0\n    grams = [tuple(tokens[i:i + n]) for i in range(len(tokens) - n + 1)]\n    if not grams:\n        return 0.0\n    return float(len(set(grams)) / len(grams))\n\n\ndef _form_fidelity(text: str, constraint: Constraint) -> float:\n    \"\"\"Heuristic form-fidelity: try syllable / required-token checks if they're hinted.\"\"\"\n    score = 1.0\n    constraint_text = constraint.text.lower()\n    if \"haiku\" in constraint_text:\n        # Haiku target: 17 syllables, ±3 tolerance.\n        s = _count_syllables(text)\n        diff = abs(s - 17) / 17.0\n        score *= max(0.0, 1.0 - diff)\n    if \"5-7-5\" in constraint_text:\n        lines = [ln for ln in text.splitlines() if ln.strip()]\n        if len(lines) >= 3:\n            sylls = [_count_syllables(ln) for ln in lines[:3]]\n            target = [5, 7, 5]\n            diff = sum(abs(s - t) for s, t in zip(sylls, target, strict=False)) / max(1, sum(target))\n            score *= max(0.0, 1.0 - diff)\n        else:\n            score *= 0.3\n    if \"haiku\" not in constraint_text and \"5-7-5\" not in constraint_text:\n        # No specific form hint: form_fidelity defaults to 0.7 (neutral) so it\n        # doesn't dominate the aggregate without a reason.\n        score = 0.7\n    return float(max(0.0, min(1.0, score)))\n\n\ndef ananda(\n    candidate: Candidate,\n    *,\n    constraint: Constraint,\n    embed: Embedder,\n    reward: float | None = None,\n    weights: dict[str, float] | None = None,\n) -> float:\n    \"\"\"Returns a scalar reward in [0, 1].\"\"\"\n    if not candidate.text.strip():\n        return 0.0\n\n    w = dict(weights or DEFAULT_WEIGHTS)\n    # If no reward model provided, redistribute its weight onto the other axes proportionally.\n    if reward is None:\n        rw = w.pop(\"reward_model\", 0.0)\n        norm = sum(w.values()) or 1.0\n        for k in list(w):\n            w[k] = float(w[k]) * (1.0 + rw / norm)\n\n    coherence = float(embed.cosine(candidate.embedding, constraint.embedding))\n    coherence = max(0.0, min(1.0, (coherence + 1.0) / 2.0))  # cosine [-1,1] -> [0,1]\n\n    tokens = candidate.text.split()\n    div2 = _distinct_n(tokens, 2)\n    div3 = _distinct_n(tokens, 3)\n    diversity = float(0.5 * div2 + 0.5 * div3)\n\n    form = _form_fidelity(candidate.text, constraint)\n\n    score = (\n        w.get(\"coherence\", 0.0) * coherence\n        + w.get(\"diversity\", 0.0) * diversity\n        + w.get(\"form_fidelity\", 0.0) * form\n    )\n    if reward is not None:\n        score += w.get(\"reward_model\", 0.0) * float(max(0.0, min(1.0, reward)))\n    return float(max(0.0, min(1.0, score)))\n",
 "pce-poem/pce/operators/apohana.py": "\"\"\"`apohana-śakti` - contrastive exclusion (anti-non-X scoring).\n\nFor each candidate, return cos(c_k, q) - max_n cos(c_k, n) where q is the\nconstraint embedding and n ranges over the constraint's `must_avoid`\nexemplars.\n\nv0.2 (ADR-002): adds an opt-in `normalize` flag that min-max-shifts the raw\ncontrastive score into `[0, 1]` over the K candidates of the current call.\nThe shift is idempotent on inputs already in `[0, 1]`. Default\n`normalize=False` preserves backward compatibility for direct callers; the\ntwo-pass cascade in `pce.cascade.run_cascade` passes `normalize=True`.\n\nv0.3 (ADR-004): adds an opt-in ``hopfield`` warm-start. When the cascade\nthreads in a per-domain :class:`pce.active_inference.HopfieldStore`, each\ncandidate's apoha score is augmented by ``hopfield_weight * att_k`` where\n``att_k`` is the Hopfield softmax mass of the candidate against the stored\npatterns. This biases jñāna toward candidates that resemble previously\nconsolidated successful surfaces in the same domain. Default\n``hopfield=None`` reproduces v0.2 exactly.\n\"\"\"\nfrom __future__ import annotations\n\nimport numpy as np\nimport numpy.typing as npt\n\nfrom pce.active_inference.hopfield import HopfieldStore\nfrom pce.substrate.embed import Embedder\nfrom pce.types import Candidate, Constraint\n\n\ndef _shift_apoha(x: npt.NDArray[np.float32]) -> npt.NDArray[np.float32]:\n    \"\"\"Min-max shift K raw apoha scores into [0, 1]; idempotent on [0, 1] input.\n\n    Used by both `apohana(normalize=True)` and `jnana` (which applies the shift\n    unconditionally on the input it receives, per ADR-002). The shift collapses\n    to a constant 0.5 vector when all K candidates have identical apoha so the\n    pseudo-counts stay symmetric in that degenerate case.\n    \"\"\"\n    if x.size == 0:\n        return x.astype(np.float32, copy=False)\n    arr = np.asarray(x, dtype=np.float64)\n    lo = float(arr.min())\n    hi = float(arr.max())\n    if hi - lo < 1e-9:\n        return np.full_like(arr, 0.5, dtype=np.float32)\n    return ((arr - lo) / (hi - lo)).astype(np.float32)\n\n\ndef apohana(\n    candidates: tuple[Candidate, ...],\n    constraint: Constraint,\n    *,\n    embed: Embedder,\n    normalize: bool = False,\n    hopfield: HopfieldStore | None = None,\n    hopfield_weight: float = 0.25,\n) -> npt.NDArray[np.float32]:\n    if not candidates:\n        return np.zeros((0,), dtype=np.float32)\n    cand_emb = np.stack([c.embedding for c in candidates], axis=0).astype(np.float32)\n    q = constraint.embedding\n    pos = cand_emb @ q  # shape (K,)\n    if not constraint.must_avoid:\n        raw = pos.astype(np.float32)\n    else:\n        avoid_emb: np.ndarray = embed.encode(list(constraint.must_avoid))  # type: ignore[type-arg]\n        if avoid_emb.ndim == 1:\n            avoid_mat = avoid_emb[None, :]\n        else:\n            avoid_mat = avoid_emb\n        neg = cand_emb @ avoid_mat.T  # shape (K, n_avoid)\n        neg_max = neg.max(axis=1)\n        raw = (pos - neg_max).astype(np.float32)\n    if hopfield is not None and hopfield.n_patterns > 0:\n        # Warm-start: per-candidate softmax mass under the Hopfield query.\n        # We query the storehouse with each candidate's embedding and use the\n        # MAX of stored-pattern cosine as the per-candidate retrieval signal,\n        # then min-max normalize across K so the warm-start is on a comparable\n        # scale to apoha. This stays bounded and never erases the apoha signal.\n        bonus = np.zeros((cand_emb.shape[0],), dtype=np.float32)\n        for k in range(cand_emb.shape[0]):\n            res = hopfield.query(cand_emb[k])\n            # Use the max cosine to any stored pattern, derived from energy =\n            # -1/beta * logsumexp(beta * sims). We approximate by the softmax-\n            # weighted retrieval norm: ||retrieved|| since patterns are unit norm.\n            norm = float(np.linalg.norm(res.retrieved))\n            bonus[k] = min(1.0, max(0.0, norm))\n        bonus_norm = _shift_apoha(bonus)\n        raw = (raw + np.float32(hopfield_weight) * bonus_norm).astype(np.float32)\n    if normalize:\n        return _shift_apoha(raw)\n    return raw\n",
 "pce-poem/pce/operators/cit.py": "\"\"\"`cit` - luminous-ground generative prior.\n\n`cit` is the cascade's bottom layer: a temperature-scheduled token sampler over\nthe local LM. The operator is a thin, deterministic-on-seed wrapper around\n`LocalLM.generate` that exists so the cascade can address the substrate by its\nPratyabhijna name and so the operator-spec invariants live in one place.\n\nSemantics (see [docs/operator-spec.md §1](../../../docs/operator-spec.md#1-cit--luminous-ground-generative-prior)).\n\"\"\"\nfrom __future__ import annotations\n\nfrom pce.substrate.lm_protocol import LMProtocol\nfrom pce.types import Candidate\n\n\ndef cit(\n    prompt: str,\n    *,\n    lm: LMProtocol,\n    temperature: float = 1.0,\n    max_tokens: int = 64,\n    top_p: float = 0.95,\n    top_k: int = 50,\n    seed: int = 0,\n) -> Candidate:\n    \"\"\"Sample one continuation from the LM under (temperature, top_p, top_k, seed).\"\"\"\n    if temperature <= 0:\n        raise ValueError(f\"cit: temperature must be > 0, got {temperature}\")\n    if max_tokens <= 0:\n        raise ValueError(f\"cit: max_tokens must be > 0, got {max_tokens}\")\n    return lm.generate(\n        prompt,\n        max_tokens=int(max_tokens),\n        sampler={\"tau\": float(temperature), \"top_p\": float(top_p), \"top_k\": float(top_k)},\n        seed=int(seed),\n    )\n",
 "pce-poem/pce/operators/iccha.py": "\"\"\"`icchā` - pre-cognitive directional vector.\n\nEmit K candidate continuations under K samplers. v0.2 introduces two parity\nknobs (ADR-005) so the cascade arm sees the *same prompt* and *same sampler\ndistribution* as the bare arm; per-K diversity comes from the seed only:\n\n* ``prompt_mode=\"verbatim\"`` (default) returns the user prompt unchanged;\n  the constraint is communicated downstream only via the ``Constraint``\n  object that ``apohana`` and ``vimarsa`` consume. ``\"constraint_suffix\"``\n  preserves the v0.1 behavior of appending\n  ``\"Write a response that is <constraint>.\"`` for direct callers that want\n  the legacy prompt.\n* ``sampler_grid_mode=\"parity\"`` (default) ignores ``sampler_grid`` and\n  emits K identical samplers ``{\"tau\": 0.9, \"top_p\": 0.95, \"top_k\": 50}`` -\n  exactly what the bare baseline uses. ``\"grid\"`` falls back to the v0.1\n  explore-exploit grid (or a caller-supplied ``sampler_grid``).\n\nThe substrate is now ``LMProtocol`` so cascade can run against either\n``LocalLM`` (Qwen2-1.5B) or ``HaikuLM`` (Anthropic Haiku via ``claude``\nCLI). Both implementations honor ``seed`` so per-K candidate diversity in\nparity mode is purely seed-driven.\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Literal\n\nfrom pce.operators.cit import cit\nfrom pce.substrate.lm_protocol import LMProtocol\nfrom pce.types import Candidate, Constraint\n\n# v0.1 explore-exploit grid kept for backward compatibility under\n# `sampler_grid_mode=\"grid\"` and direct callers passing `sampler_grid=`.\nDEFAULT_SAMPLER_GRID: tuple[dict[str, float], ...] = (\n    {\"tau\": 0.40, \"top_p\": 0.92, \"top_k\": 30.0},\n    {\"tau\": 0.60, \"top_p\": 0.94, \"top_k\": 40.0},\n    {\"tau\": 0.80, \"top_p\": 0.95, \"top_k\": 50.0},\n    {\"tau\": 0.95, \"top_p\": 0.95, \"top_k\": 50.0},\n    {\"tau\": 1.10, \"top_p\": 0.96, \"top_k\": 60.0},\n    {\"tau\": 1.30, \"top_p\": 0.97, \"top_k\": 80.0},\n    {\"tau\": 1.50, \"top_p\": 0.98, \"top_k\": 100.0},\n    {\"tau\": 1.80, \"top_p\": 0.99, \"top_k\": 0.0},\n)\n\n# v0.2 parity grid: K copies of the bare baseline's sampler. Different *seeds*\n# across K give the candidate diversity, not different temperatures. This\n# makes (cascade - bare) a clean architectural ablation per ADR-005.\n#\n# v0.3 (ADR-003): the parity sampler's ``tau`` is multiplicatively modulated\n# by the cascade's ``cit_temperature`` so the cit operator can re-temper the\n# K-fan-out posterior. ``effective_tau = base_tau * cit_temperature``. The\n# default ``base_tau = 0.9`` matches v0.2 exactly when ``cit_temperature == 1``.\nPARITY_BASE_TAU: float = 0.9\nPARITY_SAMPLER: dict[str, float] = {\"tau\": PARITY_BASE_TAU, \"top_p\": 0.95, \"top_k\": 50.0}\n\n# v0.4 (ADR-001): the Haiku CLI substrate does not expose token-level sampler\n# flags, so ``cit_temperature`` cannot causally modulate token probabilities\n# under the OAuth-only constraint. v0.4 makes ``cit_temperature`` causal via\n# *best-of-K candidate width*: the runtime number of candidates is a function\n# of ``cit_temperature`` and each candidate gets a deterministic prompt-level\n# diversity perturbation drawn from a frozen 8-element table indexed by the\n# seed. Posterior selection inside ``iccha`` (parity tau, ananda, jnana) is\n# unchanged.\n#\n# At ``cit_temperature = 0.0``, ``K_runtime = round(0.5 * K_eff)`` (concentrated\n# around the central reading). At ``cit_temperature = 1.0``, ``K_runtime =\n# round(2.0 * K_eff)`` (broader exploration). The formula's neutral point\n# (``K_runtime == K_eff``) is at ``cit_temperature = 1/3``; the v0.4 pilot\n# default ``cit_temperature = 0.5`` deliberately sits slightly above neutral\n# so the proxy probes a wider candidate front than the v0.3 default did.\nK_MIN: int = 2\nK_MAX: int = 16\n\n# Frozen 8-element prompt-perturbation table. Each entry is prepended to the\n# prompt as a single-line nudge. Index is computed as ``(seed % 8 + i) % 8``.\n# Index 0 (identity) preserves the v0.3 prompt verbatim so K_runtime == K_eff\n# at cit_temperature == 0.5 produces the same surface as v0.3 for the central\n# candidate.\nPERTURBATION_TABLE: tuple[str, ...] = (\n    \"\",\n    \"Lean toward the literal interpretation. \",\n    \"Lean toward the figurative interpretation. \",\n    \"Foreground the unusual aspect of the prompt. \",\n    \"Foreground the conventional aspect of the prompt. \",\n    \"Use one specific concrete image. \",\n    \"Use one abstract or universal frame. \",\n    \"Reframe in one alternative perspective. \",\n)\n\nPromptMode = Literal[\"verbatim\", \"constraint_suffix\"]\nSamplerGridMode = Literal[\"parity\", \"grid\"]\n\n\ndef k_runtime_for(K_eff: int, cit_temperature: float) -> int:\n    \"\"\"Compute v0.4 best-of-K width as a function of ``cit_temperature``.\n\n    Per ADR-001:\n\n        K_runtime = clip(round(K_eff * (0.5 + 1.5 * cit_temperature)), K_MIN, K_MAX)\n\n    Pure function so it can be tested independently of an LM substrate.\n    \"\"\"\n    if K_eff <= 0:\n        raise ValueError(f\"icchā: K_eff must be > 0, got {K_eff}\")\n    if cit_temperature < 0:\n        raise ValueError(f\"icchā: cit_temperature must be >= 0, got {cit_temperature}\")\n    raw = round(float(K_eff) * (0.5 + 1.5 * float(cit_temperature)))\n    return max(K_MIN, min(K_MAX, int(raw)))\n\n\ndef perturbation_idx(seed: int, k: int) -> int:\n    \"\"\"Deterministic perturbation index for candidate ``k`` of an item with ``seed``.\"\"\"\n    return (int(seed) % 8 + int(k)) % 8\n\n\ndef perturbation_for(seed: int, k: int) -> str:\n    \"\"\"Look up the prompt-level perturbation for candidate ``k`` of seed ``seed``.\"\"\"\n    return PERTURBATION_TABLE[perturbation_idx(seed, k)]\n\n\ndef _build_prompt(\n    prompt: str, constraint: Constraint, *, prompt_mode: PromptMode = \"verbatim\"\n) -> str:\n    \"\"\"Wrap user prompt with the constraint cue inlined as natural prose.\n\n    v0.2: the default ``prompt_mode`` is ``\"verbatim\"``: the prompt is\n    returned unchanged so the cascade arm sees the same string as the bare\n    arm. ``\"constraint_suffix\"`` preserves the v0.1 behavior used by direct\n    callers and the legacy ``sampler_grid_mode=\"grid\"`` path; small models\n    (Qwen2-1.5B) sometimes echo a literal ``[Constraint: ...]`` bracket so\n    we use natural prose for the suffix.\n    \"\"\"\n    if not prompt.strip():\n        raise ValueError(\"icchā: prompt must be non-empty\")\n    if prompt_mode == \"verbatim\":\n        return prompt\n    if prompt_mode == \"constraint_suffix\":\n        return f\"{prompt.rstrip()}\\nWrite a response that is {constraint.text}.\\n\\n\"\n    raise ValueError(f\"icchā: unknown prompt_mode={prompt_mode!r}\")\n\n\ndef iccha(\n    prompt: str,\n    constraint: Constraint,\n    *,\n    lm: LMProtocol,\n    K: int = 8,\n    sampler_grid: tuple[dict[str, float], ...] | None = None,\n    sampler_grid_mode: SamplerGridMode = \"parity\",\n    prompt_mode: PromptMode = \"verbatim\",\n    base_seed: int = 0,\n    max_tokens: int = 64,\n    cit_temperature: float = 1.0,\n    cit_temperature_mechanism: Literal[\"best_of_k\", \"parity_tau\", \"off\"] = \"best_of_k\",\n) -> tuple[Candidate, ...]:\n    \"\"\"Generate candidate continuations.\n\n    The caller supplies a *nominal* ``K`` (``K_eff``); the runtime candidate\n    count depends on ``cit_temperature`` under the v0.4 best-of-K mechanism\n    (ADR-001). At ``cit_temperature = 0.5`` the runtime count equals\n    ``K_eff``; at ``cit_temperature = 1.0`` it doubles; at ``0.0`` it halves.\n\n    ``cit_temperature_mechanism`` selects how ``cit_temperature`` enters:\n\n    * ``\"best_of_k\"`` (default, v0.4 ADR-001): runtime K width scales with\n      ``cit_temperature``; each candidate gets a deterministic prompt-level\n      perturbation indexed by ``(seed % 8, i % 8)``; parity ``tau`` stays at\n      ``PARITY_BASE_TAU = 0.9``. This is the headline causal mechanism for\n      Haiku CLI substrates that do not expose token-level sampler flags.\n    * ``\"parity_tau\"`` (v0.3 behavior): no width modulation; parity ``tau``\n      is multiplied by ``cit_temperature``. Kept for backward compatibility\n      and for substrates where token-level temperature *is* honored\n      (LocalLM, SDK).\n    * ``\"off\"``: ``cit_temperature`` is recorded on the audit but does not\n      enter generation. Used by the prove-gate as a control.\n\n    Per :class:`Candidate.sampler` the audit log preserves\n    ``cit_temperature``, ``K_eff``, ``K_runtime``, ``perturbation_idx``, and\n    ``cit_temperature_mechanism``.\n    \"\"\"\n    if K <= 0:\n        raise ValueError(f\"icchā: K must be > 0, got {K}\")\n    if cit_temperature < 0:\n        raise ValueError(f\"icchā: cit_temperature must be >= 0, got {cit_temperature}\")\n\n    K_eff = int(K)\n    # v0.4 (ADR-001): width-expansion via cit_temperature is the production\n    # mechanism. It applies only to the parity sampler path (the default and\n    # the only path used by the cascade). Grid mode is the v0.1 legacy\n    # explore-exploit ladder; it preserves v0.3 semantics (K_runtime == K_eff\n    # and \"grid too small raises\") so caller contracts do not silently change.\n    if cit_temperature_mechanism == \"best_of_k\" and sampler_grid_mode == \"parity\":\n        K_runtime = k_runtime_for(K_eff, cit_temperature)\n    else:\n        K_runtime = K_eff\n\n    if sampler_grid_mode == \"parity\":\n        if cit_temperature_mechanism == \"parity_tau\":\n            modulated_tau = float(PARITY_BASE_TAU) * float(cit_temperature)\n        else:\n            # best_of_k or off: parity tau stays at the v0.2 base so width is\n            # the only causal handle on output diversity.\n            modulated_tau = float(PARITY_BASE_TAU)\n        parity = dict(PARITY_SAMPLER)\n        parity[\"tau\"] = modulated_tau\n        grid: tuple[dict[str, float], ...] = tuple(dict(parity) for _ in range(K_runtime))\n    elif sampler_grid_mode == \"grid\":\n        grid = sampler_grid or DEFAULT_SAMPLER_GRID\n        if len(grid) < K_runtime:\n            raise ValueError(\n                f\"icchā: sampler_grid has {len(grid)} entries, need at least K={K_runtime}\"\n            )\n    else:\n        raise ValueError(f\"icchā: unknown sampler_grid_mode={sampler_grid_mode!r}\")\n\n    full_prompt = _build_prompt(prompt, constraint, prompt_mode=prompt_mode)\n    candidates: list[Candidate] = []\n    for k in range(K_runtime):\n        spec = grid[k]\n        if cit_temperature_mechanism == \"best_of_k\":\n            p_idx = perturbation_idx(int(base_seed), k)\n            perturbation = PERTURBATION_TABLE[p_idx]\n            generation_prompt = (perturbation + full_prompt) if perturbation else full_prompt\n        else:\n            p_idx = 0\n            generation_prompt = full_prompt\n        cand = cit(\n            generation_prompt,\n            lm=lm,\n            temperature=float(spec.get(\"tau\", 1.0)),\n            top_p=float(spec.get(\"top_p\", 0.95)),\n            top_k=int(spec.get(\"top_k\", 50)),\n            max_tokens=max_tokens,\n            seed=int(base_seed) + k,\n        )\n        new_sampler = dict(cand.sampler)\n        new_sampler[\"cit_temperature\"] = float(cit_temperature)\n        new_sampler[\"K_eff\"] = float(K_eff)\n        new_sampler[\"K_runtime\"] = float(K_runtime)\n        new_sampler[\"perturbation_idx\"] = float(p_idx)\n        new_sampler[\"cit_temperature_mechanism\"] = float(\n            {\"best_of_k\": 1.0, \"parity_tau\": 2.0, \"off\": 0.0}[cit_temperature_mechanism]\n        )\n        cand = Candidate(\n            seed=cand.seed,\n            sampler=new_sampler,\n            tokens=cand.tokens,\n            text=cand.text,\n            logp=cand.logp,\n            embedding=cand.embedding,\n        )\n        candidates.append(cand)\n    return tuple(candidates)\n",
 "pce-poem/pce/operators/jnana.py": "\"\"\"`jñāna` - Bayesian Model Reduction posterior selection.\n\nImplements the categorical-Dirichlet BMR equations from\n[docs/research-extended.md §2.3](../../../docs/research-extended.md#23-reducer-pseudocode-used-as-jnana-core)\nin log-space using `scipy.special.gammaln`.\n\nThe full prior is constructed from a uniform Dirichlet `Dir(1,1,...,1)` of\nlength K updated with pseudo-counts\n`α_k = 1 + λ_a · ananda_k + λ_p · shift(apoha_k)` (v0.2: ADR-002), where\n`shift` is a min-max normalization into `[0, 1]`. K reduced priors are then\nenumerated; ΔF for each is computed via the log-Beta form.\n\nv0.2 change: the v0.1 `np.clip(apoha, 0., None)` discarded negative apoha\nevidence (P1-4 in the adversarial review). The min-max shift in `apohana`\npreserves the relative ordering of must-avoid penalties so candidates close\nto the avoid set lose posterior mass instead of tying with neutral\ncandidates.\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Literal\n\nimport numpy as np\nimport numpy.typing as npt\nfrom scipy.special import gammaln\n\nfrom pce.operators.apohana import _shift_apoha\n\nEPS = 1e-7\n# v0.3 ADR-003: cosine threshold for \"candidate satisfies aspect i\" used by\n# the aspect-conditioned reductions. Tuned against the duck-rabbit fixture\n# where MiniLM avg-pooling gives ~0.30-0.45 cosine on hits and <0.20 on\n# misses. The same floor is used by vimarsa for aspect counting; we rebind\n# here rather than importing vimarsa to keep the operator boundary clean.\nASPECT_HIT_FLOOR = 0.30\nReductionTarget = Literal[\"halve\", \"single\", \"custom\", \"aspect_conditioned\"]\n\n\ndef _log_beta(a: npt.NDArray[np.float64]) -> float:\n    \"\"\"Log of multivariate Beta normalizer = sum_i lgamma(a_i) - lgamma(sum_i a_i).\"\"\"\n    return float(np.sum(gammaln(a)) - gammaln(np.sum(a)))\n\n\ndef _delta_F(\n    a_post: npt.NDArray[np.float64],\n    full_prior: npt.NDArray[np.float64],\n    reduced_prior: npt.NDArray[np.float64],\n) -> tuple[float, npt.NDArray[np.float64]]:\n    tilde_a_post = a_post + reduced_prior - full_prior\n    if np.any(tilde_a_post <= 0):\n        return float(\"-inf\"), reduced_prior.copy()\n    delta = (\n        _log_beta(tilde_a_post)\n        - _log_beta(a_post)\n        + _log_beta(full_prior)\n        - _log_beta(reduced_prior)\n    )\n    return float(delta), tilde_a_post\n\n\ndef _enumerate_aspect_conditioned_reductions(\n    K: int,\n    aspect_membership: npt.NDArray[np.float32],\n    aspect_priors: npt.NDArray[np.float32] | None,\n    *,\n    boost: float = 4.0,\n) -> list[npt.NDArray[np.float64]]:\n    \"\"\"Enumerate one reduction per non-empty aspect subset (S_i).\n\n    ``aspect_membership`` is a (K, A) matrix of cosine similarities between\n    candidate ``k`` and aspect ``i``; values in roughly ``[-1, 1]``. We\n    binarize at ``aspect_membership >= ASPECT_HIT_FLOOR`` to get the\n    aspect→candidate support sets. Each non-empty support set becomes one\n    reduced prior that **boosts** the in-support concentration parameters\n    relative to the uniform full prior.\n\n    Per ADR-003 we use a *soft* reduction (boost concentration to ``1+boost``\n    for in-support, keep ``1.0`` for out-of-support, and weight the boost by\n    the aspect prior) rather than a *hard* reduction (EPS for out-of-support)\n    because hard reductions blow up ``log Z(reduced_prior)`` via\n    ``lgamma(EPS) ≈ 16`` and make ΔF deeply negative on every IFR reduction\n    even when the surface satisfies the aspect. The soft form keeps the BMR\n    posterior contrast informative (positive ΔF on real aspect coverage).\n\n    We also include:\n\n    * The intersection of all aspect supports (the IFR reduction the cascade\n      hopes will win on duck-rabbit-like items), with a slightly stronger\n      boost ``boost * 1.5``.\n    * The unchanged full prior so jñāna can \"decline to reduce\" when no\n      aspect is satisfied -- this is the calibration baseline against which\n      ΔF is measured.\n\n    Returns a list of length-K float64 priors, all entries ``>= 1.0`` so\n    ``lgamma`` stays bounded.\n    \"\"\"\n    if aspect_membership.shape[0] != K:\n        raise ValueError(\n            f\"jnana: aspect_membership rows must equal K={K}, got {aspect_membership.shape}\"\n        )\n    A = int(aspect_membership.shape[1])\n    out: list[npt.NDArray[np.float64]] = []\n    if aspect_priors is None or aspect_priors.shape[0] != A or float(aspect_priors.sum()) <= 0.0:\n        priors = np.ones((A,), dtype=np.float64) / max(A, 1)\n    else:\n        priors = np.asarray(aspect_priors, dtype=np.float64)\n        priors = priors / float(priors.sum() + 1e-30)\n    hit = (aspect_membership >= ASPECT_HIT_FLOOR).astype(np.float64)  # (K, A)\n    base = float(boost)\n    # Per-aspect support reductions: boost in-support, leave others at 1.\n    any_support = False\n    for i in range(A):\n        support = hit[:, i] > 0.5\n        if not bool(support.any()):\n            continue\n        any_support = True\n        r = np.ones((K,), dtype=np.float64)\n        r[support] = 1.0 + base * float(priors[i] * A)  # rescale so total prior mass tracks A\n        out.append(r)\n    # IFR reduction: candidates that hit every aspect, boosted harder.\n    if A > 0:\n        full_support = hit.sum(axis=1) >= float(A)\n        if bool(full_support.any()):\n            any_support = True\n            r = np.ones((K,), dtype=np.float64)\n            r[full_support] = 1.0 + base * 1.5\n            out.append(r)\n    # Always include the unchanged full prior so jnana can \"decline to reduce\".\n    out.append(np.ones((K,), dtype=np.float64))\n    if not any_support and len(out) == 1:\n        # No aspect ever hit; the only entry is the uniform reduction.\n        # Append a zero-boost copy so the loop in jnana has at least 2 candidates.\n        out.append(np.ones((K,), dtype=np.float64))\n    return out\n\n\ndef _enumerate_reductions(\n    K: int, target: ReductionTarget, pseudo_counts: npt.NDArray[np.float64],\n    custom: list[npt.NDArray[np.float64]] | None,\n    aspect_membership: npt.NDArray[np.float32] | None = None,\n    aspect_priors: npt.NDArray[np.float32] | None = None,\n) -> list[npt.NDArray[np.float64]]:\n    flat = np.ones((K,), dtype=np.float64)\n    out: list[npt.NDArray[np.float64]] = []\n    if target == \"single\":\n        for k in range(K):\n            r = np.full((K,), EPS, dtype=np.float64)\n            r[k] = 1.0\n            out.append(r)\n        return out\n    if target == \"halve\":\n        # Each reduction keeps the top-half by pseudo-count.\n        order = np.argsort(-pseudo_counts)  # descending\n        half = max(1, K // 2)\n        keep_top = set(order[:half].tolist())\n        r1 = np.full((K,), EPS, dtype=np.float64)\n        for k in keep_top:\n            r1[k] = 1.0\n        out.append(r1)\n        # And one reduction that keeps each single candidate (single-survivor).\n        for k in range(K):\n            r = np.full((K,), EPS, dtype=np.float64)\n            r[k] = 1.0\n            out.append(r)\n        # And the unchanged full-prior baseline.\n        out.append(flat.copy())\n        return out\n    if target == \"custom\":\n        if not custom:\n            raise ValueError(\"jnana: reduction_target='custom' requires explicit `custom` priors\")\n        return list(custom)\n    if target == \"aspect_conditioned\":\n        if aspect_membership is None:\n            raise ValueError(\n                \"jnana: reduction_target='aspect_conditioned' requires `aspect_membership`\"\n            )\n        return _enumerate_aspect_conditioned_reductions(K, aspect_membership, aspect_priors)\n    raise ValueError(f\"unknown reduction_target: {target}\")\n\n\ndef jnana(\n    candidates: tuple[object, ...],\n    apoha_scores: npt.NDArray[np.float32],\n    ananda_scores: npt.NDArray[np.float32],\n    *,\n    reduction_target: ReductionTarget = \"halve\",\n    custom_priors: list[npt.NDArray[np.float64]] | None = None,\n    lambda_a: float = 2.0,\n    lambda_p: float = 2.0,\n    aspect_membership: npt.NDArray[np.float32] | None = None,\n    aspect_priors: npt.NDArray[np.float32] | None = None,\n) -> tuple[int, float, npt.NDArray[np.float32]]:\n    \"\"\"Returns (selected_index, best_delta_F, posterior).\n\n    `selected_index` is the candidate that survives the winning reduction\n    (i.e. the argmax of the reduced posterior).\n\n    v0.3 (ADR-003): when ``reduction_target=\"aspect_conditioned\"`` the BMR\n    enumerates one reduction per aspect support set (and one IFR reduction\n    over the full intersection). ``aspect_membership`` is a (K, A) matrix\n    of aspect-cosine scores per candidate, and ``aspect_priors`` is an\n    optional (A,) prior over aspects (typically the storehouse-attended\n    aspect mass returned by :class:`pce.active_inference.HopfieldStore`).\n    The non-degenerate ΔF this produces is what the active-inference\n    uplift gate measures.\n    \"\"\"\n    K = len(candidates)\n    if K < 2:\n        raise ValueError(f\"jnana: need K >= 2 candidates, got {K}\")\n    if apoha_scores.shape != (K,) or ananda_scores.shape != (K,):\n        raise ValueError(\n            f\"jnana: score shapes must be ({K},), got apoha={apoha_scores.shape} ananda={ananda_scores.shape}\"\n        )\n    apoha = apoha_scores.astype(np.float32)\n    anan = ananda_scores.astype(np.float64)\n    apoha_shift = _shift_apoha(apoha).astype(np.float64)\n    pseudo = 1.0 + float(lambda_a) * anan + float(lambda_p) * apoha_shift\n\n    full_prior = np.ones((K,), dtype=np.float64)\n    a_post = full_prior + pseudo - 1.0  # i.e. = pseudo\n\n    reductions = _enumerate_reductions(\n        K, reduction_target, pseudo, custom_priors,\n        aspect_membership=aspect_membership,\n        aspect_priors=aspect_priors,\n    )\n    best_delta = float(\"-inf\")\n    best_post: npt.NDArray[np.float64] = full_prior / full_prior.sum()\n    for r in reductions:\n        delta, tilde = _delta_F(a_post, full_prior, r)\n        if delta > best_delta:\n            best_delta = delta\n            best_post = tilde / max(tilde.sum(), 1e-30)\n\n    sel = int(np.argmax(best_post))\n    return sel, float(best_delta), best_post.astype(np.float32)\n\n\ndef log_beta(a: npt.NDArray[np.float64]) -> float:\n    \"\"\"Public re-export of `_log_beta` for tests.\"\"\"\n    return _log_beta(a)\n",
 "pce-poem/pce/operators/kriya.py": "\"\"\"`kriyā` - surface enaction.\n\nTurns the selected `Candidate` into a final surface text. Three render modes\ndocumented in [docs/operator-spec.md §6](../../../docs/operator-spec.md#6-kriya--surface-enaction):\n\n* `verbatim`     - identity on `selected.text`.\n* `polish`       - re-pass through the local LM with a low-temperature polish prompt.\n* `claude_polish`- delegate to a caller-supplied Claude renderer.\n\"\"\"\nfrom __future__ import annotations\n\nfrom collections.abc import Callable\nfrom typing import Literal\n\nfrom pce.substrate.embed import Embedder\nfrom pce.substrate.lm_protocol import LMProtocol\nfrom pce.types import Candidate\n\nRenderMode = Literal[\"verbatim\", \"polish\", \"claude_polish\"]\n\n\ndef kriya(\n    selected: Candidate,\n    *,\n    render_mode: RenderMode = \"verbatim\",\n    lm: LMProtocol | None = None,\n    embed: Embedder | None = None,\n    claude_renderer: Callable[[str], str] | None = None,\n    polish_max_tokens: int = 96,\n) -> str:\n    text = selected.text\n    if render_mode == \"verbatim\":\n        return text\n    if render_mode == \"polish\":\n        if lm is None:\n            raise ValueError(\"kriya: render_mode='polish' requires `lm`\")\n        prompt = (\n            \"Refine the following text, preserving its meaning, imagery, and overall length.\"\n            \"\\n\\nText:\\n\" + text + \"\\n\\nRefined:\\n\"\n        )\n        polished = lm.generate(\n            prompt,\n            max_tokens=polish_max_tokens,\n            sampler={\"tau\": 0.40, \"top_p\": 0.92, \"top_k\": 30.0},\n            seed=int(selected.seed) + 9001,\n        )\n        out = polished.text or text\n        if embed is not None:\n            sim = embed.cosine(selected.embedding, embed.encode(out))\n            if sim < 0.85:\n                # Polish degraded semantic fidelity; fall back to the verbatim text.\n                return text\n        return out\n    if render_mode == \"claude_polish\":\n        if claude_renderer is None:\n            raise ValueError(\"kriya: render_mode='claude_polish' requires `claude_renderer`\")\n        return str(claude_renderer(text))\n    raise ValueError(f\"unknown render_mode: {render_mode}\")\n",
 "pce-poem/pce/operators/vimarsa.py": "\"\"\"`vimarśa` - recursive aspect-shift detector and revision brief.\n\nReturns ``(event, novelty, diagnostic)`` by default and\n``(event, novelty, diagnostic, brief)`` when ``return_brief=True`` so the\ntwo-pass cascade in ``pce.cascade.run_cascade`` can feed the brief back into\n``iccha`` as a revision instruction (ADR-003).\n\nActivation criterion (conjunctive):\n\n* novelty       >= τ_n (default 0.30)\n* aspect_count  >= k   (default 1, was 2 in v0.1)\n* aesthetic     >= τ_a (default 0.40)\n* switching     >= s   (default 1) - only enforced when the caller supplies\n  an iccha/apohana trajectory of at least ``min_evidence_points`` entries;\n  treated as N/A otherwise (per ADR-003 the two-pass cascade always passes\n  ``iccha_apoha_trajectory=None``, so switching does not gate the event).\n\nv0.2 changes vs v0.1:\n\n* ``min_evidence_points`` (default 1) replaces the old hardcoded\n  ``switching_threshold=2`` which required at least two trajectory points\n  to fire. The two-pass cascade only has one observation per pass so the\n  v0.1 gate was structurally closed (P0-2 in the adversarial review).\n* ``aspect_threshold`` defaults to 1 (was 2). The duck-rabbit textual probe\n  has two aspects but small models often only realize one of them in a\n  short surface; the v0.1 floor of 2 was too strict.\n* ``return_brief=True`` makes ``vimarsa`` emit a structured revision brief\n  the cascade can feed back into the next pass. When the caller has not\n  supplied any aspects (poetry_gen, AUT) we emit a generic creative\n  revision brief instead of failing the gate on aspects.\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Literal\n\nimport numpy as np\nimport numpy.typing as npt\n\nfrom pce.active_inference.hopfield import HopfieldStore, WriteMode\nfrom pce.substrate.embed import Embedder\n\nDEFAULT_NOVELTY_THRESHOLD = 0.30\nDEFAULT_ASPECT_THRESHOLD = 1\nDEFAULT_SWITCHING_THRESHOLD = 1\nDEFAULT_MIN_EVIDENCE_POINTS = 1\n# Tuned in v0.1 phase 6 against Qwen2-1.5B surfaces and the duck-rabbit /\n# river-clock / wave-particle / candlestick-faces probe battery: 0.55 was\n# too strict for avg-pooled MiniLM embeddings on long surfaces; 0.40 fires\n# on 2/4 probes without firing on the bypass control.\nDEFAULT_ASPECT_COSINE_HIT = 0.40\nDEFAULT_AESTHETIC_FLOOR = 0.40\n# v0.3 ADR-002: vimarsa is now event-gated by ΔF as well as the v0.2 criteria.\n# When ``delta_F`` is supplied (the cascade always supplies it from jñāna's\n# draft-pass posterior), the event additionally requires\n# ``delta_F >= delta_F_threshold``. Default threshold of 0.05 bits is a\n# weak floor: any reduction with informative evidence above noise. ΔF below\n# 0.05 means jñāna couldn't pick a winner with confidence -- in that case\n# the revision pass is unlikely to help so we skip the commit-revision\n# branch and surface the draft instead.\nDEFAULT_DELTA_F_THRESHOLD = 0.05\n\nGENERIC_BRIEF = (\n    \"Refine the previous draft for novelty, vividness, and surprise. \"\n    \"Push at least one image or claim further than a baseline reading would. \"\n    \"Keep the same form and length.\"\n)\n\n\ndef _count_switching(trajectory: list[tuple[float, float]]) -> int:\n    \"\"\"Count segregated->integrated transitions.\n\n    Each entry is (entropy_iccha, entropy_apohana). A step is `integrated` iff\n    both entropies are within 25% of each other; `segregated` otherwise. We\n    count every Segregated->Integrated boundary crossing.\n    \"\"\"\n    if not trajectory:\n        return 0\n    states: list[str] = []\n    for e_i, e_a in trajectory:\n        if max(e_i, e_a) <= 0:\n            states.append(\"seg\")\n            continue\n        ratio = min(e_i, e_a) / max(e_i, e_a)\n        states.append(\"int\" if ratio >= 0.75 else \"seg\")\n    transitions = 0\n    for i in range(1, len(states)):\n        if states[i - 1] == \"seg\" and states[i] == \"int\":\n            transitions += 1\n    return transitions\n\n\ndef _build_brief(\n    *,\n    aspects: list[str],\n    aspect_sims: npt.NDArray[np.float32] | None,\n    aspect_cosine_hit: float,\n    novelty: float,\n    novelty_threshold: float,\n) -> str:\n    \"\"\"Compose a revision brief listing missing aspects + novelty pressure.\n\n    When the caller has no aspect dictionary (poetry_gen, AUT) we return the\n    generic creative brief.\n    \"\"\"\n    if not aspects or aspect_sims is None or aspect_sims.size == 0:\n        return GENERIC_BRIEF\n    sims = np.asarray(aspect_sims, dtype=np.float32)\n    missing: list[str] = [\n        aspects[i] for i in range(len(aspects)) if float(sims[i]) < float(aspect_cosine_hit)\n    ]\n    parts: list[str] = []\n    if missing:\n        formatted = \"; \".join(missing[:4])\n        parts.append(f\"Surface the following aspects that the draft did not realize: {formatted}.\")\n    if novelty < float(novelty_threshold):\n        parts.append(\"Move further from common readings - the draft was too close to obvious priors.\")\n    if not parts:\n        # Aspects all hit and novelty already cleared the bar; ask for sharpening.\n        parts.append(\"Tighten imagery and intensify the contrast between the named aspects.\")\n    return \" \".join(parts)\n\n\ndef vimarsa(\n    prompt: str,\n    surface: str,\n    *,\n    embed: Embedder,\n    retrieval_set: list[str],\n    aspects: list[str],\n    ananda_score: float,\n    iccha_apoha_trajectory: list[tuple[float, float]] | None = None,\n    novelty_threshold: float = DEFAULT_NOVELTY_THRESHOLD,\n    aspect_threshold: int = DEFAULT_ASPECT_THRESHOLD,\n    switching_threshold: int = DEFAULT_SWITCHING_THRESHOLD,\n    min_evidence_points: int = DEFAULT_MIN_EVIDENCE_POINTS,\n    aspect_cosine_hit: float = DEFAULT_ASPECT_COSINE_HIT,\n    aesthetic_floor: float = DEFAULT_AESTHETIC_FLOOR,\n    delta_F: float | None = None,\n    delta_F_threshold: float = DEFAULT_DELTA_F_THRESHOLD,\n    return_brief: bool = False,\n) -> (\n    tuple[bool, float, dict[str, float]]\n    | tuple[bool, float, dict[str, float], str]\n):\n    \"\"\"Detect an aspect-shift event over the surface text.\n\n    When ``return_brief=True`` the return is extended with a string brief\n    that the cascade can feed back into ``iccha`` for a revision pass.\n    \"\"\"\n    if not surface.strip():\n        diag_empty: dict[str, float] = {\"empty_surface\": 1.0}\n        if return_brief:\n            return False, 0.0, diag_empty, GENERIC_BRIEF\n        return False, 0.0, diag_empty\n    surf_emb = embed.encode(surface)\n    if retrieval_set:\n        retr_embs = embed.encode(list(retrieval_set))\n        if retr_embs.ndim == 1:\n            retr_embs = retr_embs[None, :]\n        sims = retr_embs @ surf_emb\n        max_sim = float(sims.max())\n    else:\n        max_sim = 0.0\n    novelty = float(max(0.0, 1.0 - max_sim))\n    aspect_sims: npt.NDArray[np.float32] | None\n    if aspects:\n        asp_embs = embed.encode(list(aspects))\n        if asp_embs.ndim == 1:\n            asp_embs = asp_embs[None, :]\n        aspect_sims = np.asarray(asp_embs @ surf_emb, dtype=np.float32)\n        aspect_count = int(np.sum(aspect_sims >= aspect_cosine_hit))\n    else:\n        aspect_sims = None\n        aspect_count = 0\n    switching = _count_switching(iccha_apoha_trajectory or [])\n    diag: dict[str, float] = {\n        \"novelty\": novelty,\n        \"max_retrieval_cosine\": max_sim,\n        \"aspect_count\": float(aspect_count),\n        \"aspect_threshold\": float(aspect_threshold),\n        \"switching\": float(switching),\n        \"switching_threshold\": float(switching_threshold),\n        \"min_evidence_points\": float(min_evidence_points),\n        \"ananda\": float(ananda_score),\n    }\n    if aspect_sims is not None:\n        diag[\"aspect_max_cosine\"] = float(aspect_sims.max())\n    novelty_ok = novelty >= float(novelty_threshold)\n    # When the domain has no aspect dictionary we treat the aspect gate as N/A\n    # (the brief becomes the generic creative brief). This unblocks\n    # poetry_gen and AUT, where v0.1 silently failed on `aspects=[]`.\n    aspect_ok = (not aspects) or aspect_count >= int(aspect_threshold)\n    aesthetic_ok = float(ananda_score) >= float(aesthetic_floor)\n    # Switching gate is only enforced when caller supplied enough trajectory\n    # evidence; otherwise treated as N/A per ADR-003.\n    if iccha_apoha_trajectory is None or len(iccha_apoha_trajectory) < int(min_evidence_points):\n        switching_ok = True\n        diag[\"switching_gate\"] = 0.0  # N/A\n    else:\n        switching_ok = switching >= int(switching_threshold)\n        diag[\"switching_gate\"] = 1.0\n    # v0.3 ADR-002: ΔF gate. When the cascade supplies a draft-pass ΔF, the\n    # event must clear `delta_F_threshold` (default 0.05 bits) on top of the\n    # v0.2 criteria. ΔF is the only signal here that comes from BMR rather\n    # than embedding heuristics, so it carries meaningful active-inference\n    # information about whether jñāna actually had evidence to commit to a\n    # winning reduction. When ``delta_F is None`` (legacy callers) the gate\n    # is N/A.\n    if delta_F is None:\n        delta_F_ok = True\n        diag[\"delta_F_gate\"] = 0.0  # N/A\n    else:\n        delta_F_ok = float(delta_F) >= float(delta_F_threshold)\n        diag[\"delta_F_gate\"] = 1.0\n        diag[\"delta_F\"] = float(delta_F)\n        diag[\"delta_F_threshold\"] = float(delta_F_threshold)\n    event = bool(novelty_ok and aspect_ok and aesthetic_ok and switching_ok and delta_F_ok)\n    if return_brief:\n        brief = _build_brief(\n            aspects=list(aspects),\n            aspect_sims=aspect_sims,\n            aspect_cosine_hit=aspect_cosine_hit,\n            novelty=novelty,\n            novelty_threshold=novelty_threshold,\n        )\n        return event, novelty, diag, brief\n    return event, novelty, diag\n\n\ndef consolidate(\n    *,\n    surface: str,\n    aspects: list[str],\n    embed: Embedder,\n    hopfield: HopfieldStore,\n    mode: WriteMode = \"rem\",\n    label_strategy: Literal[\"best_aspect\", \"first_aspect\", \"domain_only\"] = \"best_aspect\",\n) -> dict[str, object]:\n    \"\"\"Write the committed surface back to the per-domain storehouse.\n\n    v0.3 ADR-004: this is the cascade-end hook that closes the\n    iccha-apoha-jnana-kriya-vimarsa loop. The cascade calls ``consolidate``\n    after committing a surface; the storehouse then carries warm-start mass\n    for the next prompt in the same domain.\n\n    ``mode=\"rem\"`` (default) appends the surface as a new pattern (fast,\n    REM-style). ``mode=\"sws\"`` consolidates against the nearest existing\n    pattern when cosine ≥ threshold (slow-wave-style merge).\n\n    ``label_strategy``:\n\n    * ``\"best_aspect\"``: label = the aspect with the highest cosine to the\n      surface (or ``\"\"`` if no aspects supplied).\n    * ``\"first_aspect\"``: label = ``aspects[0]`` (or ``\"\"``).\n    * ``\"domain_only\"``: label = ``hopfield.domain``.\n\n    Returns a small audit dict (label, mode, n_patterns_after) for inclusion\n    on :class:`pce.types.CascadeState.audit`.\n    \"\"\"\n    if not surface.strip():\n        return {\"written\": False, \"reason\": \"empty_surface\"}\n    surf_emb = embed.encode(surface)\n    if surf_emb.ndim != 1:\n        surf_emb = np.asarray(surf_emb).reshape(-1)\n    label: str\n    if label_strategy == \"domain_only\" or not aspects:\n        label = hopfield.domain if label_strategy == \"domain_only\" else \"\"\n    elif label_strategy == \"first_aspect\":\n        label = str(aspects[0])\n    else:  # best_aspect\n        asp_embs = embed.encode(list(aspects))\n        if asp_embs.ndim == 1:\n            asp_embs = asp_embs[None, :]\n        sims = np.asarray(asp_embs @ surf_emb, dtype=np.float32)\n        label = str(aspects[int(np.argmax(sims))]) if sims.size else \"\"\n    hopfield.write(surf_emb.astype(np.float32), label=label, mode=mode)\n    return {\n        \"written\": True,\n        \"label\": label,\n        \"mode\": mode,\n        \"n_patterns_after\": int(hopfield.n_patterns),\n        \"domain\": hopfield.domain,\n    }\n",
 "pce-poem/pce/policies/__init__.py": "\"\"\"v0.4 commit-policy layer (ADR-002).\n\nRe-exports the public API: :class:`CommitPolicy`, :class:`PolicyFeatures`,\nand the five concrete policies (``AlwaysDraft``, ``AlwaysRevise``,\n``EventGated``, ``LearnedGate``, ``OracleCommit``).\n\"\"\"\nfrom __future__ import annotations\n\nfrom pce.policies.commit import (\n    AlwaysDraft,\n    AlwaysRevise,\n    CommitPolicy,\n    EventGated,\n    LearnedGate,\n    OracleCommit,\n    PolicyFeatures,\n    extract_features_from_audit,\n    policy_for_name,\n)\n\n__all__ = [\n    \"AlwaysDraft\",\n    \"AlwaysRevise\",\n    \"CommitPolicy\",\n    \"EventGated\",\n    \"LearnedGate\",\n    \"OracleCommit\",\n    \"PolicyFeatures\",\n    \"extract_features_from_audit\",\n    \"policy_for_name\",\n]\n",
 "pce-poem/pce/policies/commit.py": "\"\"\"v0.4 commit policies (ADR-002).\n\nFive commit policies decide, per-item, whether the cascade commits the shadow\nrevision or the draft surface:\n\n* :class:`AlwaysDraft`   — never commit revision (control / ablation).\n* :class:`AlwaysRevise`  — always commit revision.\n* :class:`EventGated`    — v0.3 default: commit revision iff ``vimarsa_event``.\n* :class:`LearnedGate`   — logistic regression over five scalar features\n                            extracted from the cascade audit, trained on v0.3\n                            traces with leave-one-domain-out CV.\n* :class:`OracleCommit`  — *post-hoc* analysis: pick the higher-scoring\n                            surface. Reported as an upper bound but NEVER an\n                            evaluation arm (would leak label).\n\nThe policies form a uniform :class:`CommitPolicy` ABC with a single\n``decide(features, vimarsa_event) -> bool`` method that returns ``True``\nwhen the policy chooses revision, ``False`` for draft. The cascade applies\nthe chosen policy *after* both passes have completed (``always_draft`` is\nthe only case that skips the revision pass; that is handled in\n``run_cascade`` directly so the LM-call savings are real).\n\nThis module deliberately keeps the abstract feature dataclass\n(:class:`PolicyFeatures`) detached from :class:`pce.types.CascadeState` so\nunit tests can assemble fixtures by hand and the training script can\nre-construct features from v0.3 audit JSON without instantiating a full\ncascade.\n\nLearnedGate persistence: the trained model is loaded from\n``artifacts/learned_gate_v0_4.joblib``. If the artifact is missing or\nmalformed, ``LearnedGate`` falls back to the v0.3 ``EventGated`` policy\nand records the fallback reason in ``last_fallback_reason``. The\nbenchmark driver and prove-gate surface that field so a missing artifact\nis not silently masked.\n\nPer ADR-002 the feature vector ordering is frozen:\n``[delta_F, novelty, aspect_count, ananda, budget_balance]``.\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport math\nfrom abc import ABC, abstractmethod\nfrom collections.abc import Mapping\nfrom dataclasses import asdict, dataclass\nfrom pathlib import Path\nfrom typing import Any, ClassVar, Literal\n\nREPO_ROOT = Path(__file__).resolve().parents[3]\nDEFAULT_LEARNED_GATE_PATH = REPO_ROOT / \"artifacts\" / \"learned_gate_v0_4.joblib\"\n\nPolicyName = Literal[\n    \"always_draft\", \"always_revise\", \"event_gated\", \"learned_gate\", \"oracle\"\n]\n\n\n@dataclass(frozen=True)\nclass PolicyFeatures:\n    \"\"\"Frozen 5-D feature vector consumed by every commit policy.\n\n    Ordering is locked by ADR-002 and must match the LearnedGate training\n    script. ``as_vector()`` returns a ``list[float]`` for sklearn input.\n    \"\"\"\n\n    delta_F: float\n    novelty: float\n    aspect_count: float\n    ananda: float\n    budget_balance: float\n\n    FEATURE_ORDER: ClassVar[tuple[str, ...]] = (\n        \"delta_F\",\n        \"novelty\",\n        \"aspect_count\",\n        \"ananda\",\n        \"budget_balance\",\n    )\n\n    def as_vector(self) -> list[float]:\n        \"\"\"Return [delta_F, novelty, aspect_count, ananda, budget_balance].\"\"\"\n        return [\n            float(self.delta_F),\n            float(self.novelty),\n            float(self.aspect_count),\n            float(self.ananda),\n            float(self.budget_balance),\n        ]\n\n    def to_audit(self) -> dict[str, float]:\n        return asdict(self)\n\n    @classmethod\n    def feature_names(cls) -> list[str]:\n        return list(cls.FEATURE_ORDER)\n\n\ndef _safe_float(value: Any, default: float = 0.0) -> float:\n    if value is None:\n        return float(default)\n    try:\n        f = float(value)\n    except (TypeError, ValueError):\n        return float(default)\n    if math.isnan(f) or math.isinf(f):\n        return float(default)\n    return f\n\n\ndef extract_features_from_audit(audit: Mapping[str, Any]) -> PolicyFeatures:\n    \"\"\"Build :class:`PolicyFeatures` from a v0.3 / v0.4 cascade audit dict.\n\n    The audit dict is the union of fields written by ``run_cascade`` and\n    ``benchmarks/driver.py`` for a cascade item. Missing or non-finite\n    values fall back to deterministic defaults so the feature vector is\n    always well-formed and finite (sklearn rejects NaN by default).\n\n    Recognised keys (v0.3 + v0.4):\n\n    * ``delta_F`` / ``delta_F_draft`` — preferred draft ΔF.\n    * ``novelty`` / ``vimarsa_novelty`` — vimarsa novelty score.\n    * ``vimarsa_diag.aspect_count`` / ``aspect_count`` — diagnostic aspect count.\n    * ``vimarsa_diag.ananda`` / ``ananda`` — diagnostic ananda score.\n    * ``budget_ledger.balance_bits`` / ``budget_balance`` — FE ledger balance.\n    \"\"\"\n    delta_F = _safe_float(\n        audit.get(\"delta_F_draft\", audit.get(\"delta_F\")),\n        default=0.0,\n    )\n    novelty = _safe_float(\n        audit.get(\"novelty\", audit.get(\"vimarsa_novelty\")),\n        default=0.0,\n    )\n    diag = audit.get(\"vimarsa_diag_draft\") or audit.get(\"vimarsa_diag\") or {}\n    if not isinstance(diag, Mapping):\n        diag = {}\n    aspect_count = _safe_float(\n        audit.get(\"aspect_count\", diag.get(\"aspect_count\")),\n        default=0.0,\n    )\n    ananda_val = _safe_float(\n        audit.get(\"ananda\", diag.get(\"ananda\")),\n        default=0.0,\n    )\n    ledger = audit.get(\"budget_ledger\") or {}\n    if not isinstance(ledger, Mapping):\n        ledger = {}\n    budget_balance = _safe_float(\n        audit.get(\"budget_balance\", ledger.get(\"balance_bits\")),\n        default=0.0,\n    )\n    return PolicyFeatures(\n        delta_F=delta_F,\n        novelty=novelty,\n        aspect_count=aspect_count,\n        ananda=ananda_val,\n        budget_balance=budget_balance,\n    )\n\n\nclass CommitPolicy(ABC):\n    \"\"\"ABC: decide whether to commit revision (True) or draft (False).\"\"\"\n\n    name: ClassVar[PolicyName]\n\n    @abstractmethod\n    def decide(self, features: PolicyFeatures, vimarsa_event: bool) -> bool:\n        \"\"\"Return True to commit revision, False to commit draft.\"\"\"\n\n    def to_audit(self) -> dict[str, Any]:\n        return {\"name\": self.name}\n\n\nclass AlwaysDraft(CommitPolicy):\n    \"\"\"Never commit revision. Used as the v0.4 negative-control arm.\"\"\"\n\n    name: ClassVar[PolicyName] = \"always_draft\"\n\n    def decide(self, features: PolicyFeatures, vimarsa_event: bool) -> bool:\n        return False\n\n\nclass AlwaysRevise(CommitPolicy):\n    \"\"\"Always commit revision. Used as the v0.2-style positive control.\"\"\"\n\n    name: ClassVar[PolicyName] = \"always_revise\"\n\n    def decide(self, features: PolicyFeatures, vimarsa_event: bool) -> bool:\n        return True\n\n\nclass EventGated(CommitPolicy):\n    \"\"\"v0.3 default: commit revision iff vimarsa fired.\"\"\"\n\n    name: ClassVar[PolicyName] = \"event_gated\"\n\n    def decide(self, features: PolicyFeatures, vimarsa_event: bool) -> bool:\n        return bool(vimarsa_event)\n\n\nclass LearnedGate(CommitPolicy):\n    \"\"\"Logistic regression over :class:`PolicyFeatures`.\n\n    On instantiation, attempts to load a pickled ``LogisticRegression`` plus\n    optional ``StandardScaler`` from ``model_path``. If loading fails, falls\n    back to :class:`EventGated` and records the reason in\n    ``self.last_fallback_reason``. The fallback path keeps the cascade\n    runnable in environments where the artifact has not been built yet\n    (e.g. fresh clones, CI before the training step).\n\n    The underlying model exposes ``predict_proba`` so a soft probability is\n    available alongside the binary decision. The probability is recorded\n    on every ``decide`` call in ``self.last_proba`` so the audit log can\n    surface it without needing a second forward pass.\n    \"\"\"\n\n    name: ClassVar[PolicyName] = \"learned_gate\"\n\n    def __init__(\n        self,\n        *,\n        model_path: Path | None = None,\n        threshold: float = 0.5,\n        fallback_event_gated: bool = True,\n    ) -> None:\n        self.model_path: Path = Path(model_path) if model_path else DEFAULT_LEARNED_GATE_PATH\n        self.threshold = float(threshold)\n        self.fallback_event_gated = bool(fallback_event_gated)\n        self._model: Any | None = None\n        self._scaler: Any | None = None\n        self.last_proba: float | None = None\n        self.last_fallback_reason: str | None = None\n        self._load_model()\n\n    def _load_model(self) -> None:\n        try:\n            import joblib\n        except ImportError as exc:\n            self.last_fallback_reason = f\"joblib import failed: {exc}\"\n            return\n        if not self.model_path.exists():\n            self.last_fallback_reason = (\n                f\"artifact missing: {self.model_path} (run scripts/train_learned_gate.py)\"\n            )\n            return\n        try:\n            blob = joblib.load(self.model_path)\n        except Exception as exc:  # noqa: BLE001\n            self.last_fallback_reason = f\"joblib.load failed: {type(exc).__name__}: {exc}\"\n            return\n        if isinstance(blob, dict):\n            self._model = blob.get(\"model\")\n            self._scaler = blob.get(\"scaler\")\n        else:\n            self._model = blob\n            self._scaler = None\n        if self._model is None or not hasattr(self._model, \"predict_proba\"):\n            self.last_fallback_reason = (\n                f\"loaded artifact has no predict_proba: type={type(self._model).__name__}\"\n            )\n            self._model = None\n\n    def is_loaded(self) -> bool:\n        return self._model is not None\n\n    def decide(self, features: PolicyFeatures, vimarsa_event: bool) -> bool:\n        if self._model is None:\n            if not self.fallback_event_gated:\n                # Strict mode: refuse to decide without a model.\n                self.last_proba = None\n                return False\n            decision = bool(vimarsa_event)\n            self.last_proba = None\n            return decision\n        x = [features.as_vector()]\n        if self._scaler is not None:\n            x = self._scaler.transform(x)\n        proba_arr = self._model.predict_proba(x)\n        # sklearn LogisticRegression returns shape (n_samples, n_classes).\n        # We need P(revision_better) — the positive class.\n        try:\n            classes = list(self._model.classes_)\n            pos_idx = classes.index(1) if 1 in classes else len(classes) - 1\n        except (AttributeError, ValueError):\n            pos_idx = -1\n        proba = float(proba_arr[0][pos_idx])\n        self.last_proba = proba\n        return proba >= self.threshold\n\n    def to_audit(self) -> dict[str, Any]:\n        return {\n            \"name\": self.name,\n            \"model_path\": str(self.model_path),\n            \"threshold\": float(self.threshold),\n            \"is_loaded\": bool(self.is_loaded()),\n            \"last_proba\": self.last_proba,\n            \"last_fallback_reason\": self.last_fallback_reason,\n        }\n\n\nclass OracleCommit(CommitPolicy):\n    \"\"\"Post-hoc oracle: commits whichever surface scores higher.\n\n    Requires ``draft_score`` and ``revision_score`` to be supplied via\n    :meth:`set_scores` *before* :meth:`decide` is called (the cascade\n    cannot know either score until both passes finish, and the scoring\n    happens in the benchmark driver post-hoc). NEVER use OracleCommit as\n    an evaluation arm — it leaks the label. Reported only as an upper\n    bound for the policy comparison in H8c.v4.\n    \"\"\"\n\n    name: ClassVar[PolicyName] = \"oracle\"\n\n    def __init__(self) -> None:\n        self._draft_score: float | None = None\n        self._revision_score: float | None = None\n        self.last_choice: bool | None = None\n\n    def set_scores(self, draft_score: float, revision_score: float) -> None:\n        self._draft_score = float(draft_score)\n        self._revision_score = float(revision_score)\n\n    def decide(self, features: PolicyFeatures, vimarsa_event: bool) -> bool:\n        if self._draft_score is None or self._revision_score is None:\n            raise RuntimeError(\n                \"OracleCommit.decide called before set_scores; this should never \"\n                \"appear in an evaluation arm. Use it only post-hoc with both scores.\"\n            )\n        choice = bool(self._revision_score > self._draft_score)\n        self.last_choice = choice\n        return choice\n\n    def to_audit(self) -> dict[str, Any]:\n        return {\n            \"name\": self.name,\n            \"draft_score\": self._draft_score,\n            \"revision_score\": self._revision_score,\n            \"last_choice\": self.last_choice,\n        }\n\n\n_POLICY_REGISTRY: dict[str, type[CommitPolicy]] = {\n    \"always_draft\": AlwaysDraft,\n    \"always_revise\": AlwaysRevise,\n    \"event_gated\": EventGated,\n    \"learned_gate\": LearnedGate,\n    \"oracle\": OracleCommit,\n}\n\n\ndef policy_for_name(name: str, **kwargs: Any) -> CommitPolicy:\n    \"\"\"Factory: build a :class:`CommitPolicy` instance by name.\n\n    ``kwargs`` are forwarded to the policy's constructor when supported\n    (only :class:`LearnedGate` accepts kwargs today).\n    \"\"\"\n    cls = _POLICY_REGISTRY.get(name)\n    if cls is None:\n        raise ValueError(\n            f\"unknown commit policy: {name!r}; \"\n            f\"valid={sorted(_POLICY_REGISTRY)}\"\n        )\n    if cls is LearnedGate:\n        return cls(**kwargs)\n    if kwargs:\n        raise TypeError(\n            f\"policy {name!r} does not accept kwargs (got {sorted(kwargs)})\"\n        )\n    return cls()\n\n\ndef write_policy_metadata(path: Path, payload: dict[str, Any]) -> None:\n    \"\"\"Write LearnedGate training metadata as JSON. Used by the training script.\"\"\"\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding=\"utf-8\")\n",
 "pce-poem/pce/substrate/__init__.py": "\"\"\"Substrate adapters: local LM, embeddings, Hopfield store.\n\nImplementations land in Phase 5.\n\"\"\"\n",
 "pce-poem/pce/substrate/embed.py": "\"\"\"Cloud-port embedder: deterministic signed-hash character/word n-gram vectors (numpy only).\n\nThe original uses sentence-transformers (all-MiniLM-L6-v2), which needs torch and a model download.\nThe Managed Agents sandbox has numpy/scipy but no package index or model hub, so this embedder is a\n*lexical* stand-in: same interface (L2-normalised float32, `encode`, `cosine`, `dim`), reproducible,\nscript-agnostic (works for Kannada/Tamil/Devanagari as plain code points). It captures surface\noverlap, not semantics -- see FIDELITY.md. Swap in a real model behind the same class to upgrade.\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nimport re\nfrom typing import overload\n\nimport numpy as np\nimport numpy.typing as npt\n\nDEFAULT_MODEL_ID = \"hash-ngram-512\"\n_TOKEN = re.compile(r\"\\w+\", re.UNICODE)\n\n\ndef _slot(feature: str, dim: int) -> tuple[int, float]:\n    h = hashlib.blake2b(feature.encode(\"utf-8\"), digest_size=8).digest()\n    n = int.from_bytes(h, \"little\")\n    return n % dim, 1.0 if (n >> 63) & 1 else -1.0\n\n\nclass Embedder:\n    def __init__(self, model_id: str = DEFAULT_MODEL_ID, dim: int = 512) -> None:\n        self.model_id = model_id\n        self.dim = dim\n\n    def _one(self, text: str) -> npt.NDArray[np.float32]:\n        v = np.zeros(self.dim, dtype=np.float32)\n        words = [w.lower() for w in _TOKEN.findall(text)]\n        for w in words:\n            i, s = _slot(\"w:\" + w, self.dim)\n            v[i] += 1.5 * s\n            padded = f\"^{w}$\"\n            for n in (2, 3, 4):\n                for k in range(len(padded) - n + 1):\n                    i, s = _slot(f\"c{n}:\" + padded[k : k + n], self.dim)\n                    v[i] += s\n        for a, b in zip(words, words[1:]):\n            i, s = _slot(f\"b:{a}_{b}\", self.dim)\n            v[i] += s\n        norm = float(np.linalg.norm(v))\n        if norm > 0:\n            v /= norm\n        return v\n\n    @overload\n    def encode(self, text: str) -> npt.NDArray[np.float32]: ...\n    @overload\n    def encode(self, text: list[str]) -> npt.NDArray[np.float32]: ...\n\n    def encode(self, text: str | list[str]) -> npt.NDArray[np.float32]:\n        if isinstance(text, str):\n            return self._one(text)\n        items = list(text)\n        if not items or any(not isinstance(t, str) for t in items):\n            raise ValueError(\"Embedder.encode requires a string or list[str]\")\n        return np.stack([self._one(t) for t in items]).astype(np.float32)\n\n    def cosine(self, a: npt.NDArray[np.float32], b: npt.NDArray[np.float32]) -> float:\n        if a.shape != b.shape:\n            raise ValueError(f\"Embedder.cosine shape mismatch: {a.shape} vs {b.shape}\")\n        return float(np.dot(a, b))\n",
 "pce-poem/pce/substrate/hopfield.py": "\"\"\"Hopfield-style attractor store for the ālayavijñāna substrate.\n\nA continuous Hopfield network (Krotov–Hopfield modern attractor; Ramsauer\n2020) over L2-normalized embedding vectors. The store keeps all patterns ever\nwritten and recalls the closest attractor by iterative softmax descent over\nthe inner-product energy:\n\n    E(x) = -lse(beta * X x)\n\nwith `lse` the log-sum-exp and X the matrix of stored patterns. The recall\nrule is the corresponding gradient step:\n\n    x_{t+1} = X^T softmax(beta * X x_t)\n\nThis is exact for normalized vectors and gives the storage capacity discussed\nin Ramsauer 2020 / research-extended.md §3.\n\"\"\"\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\nimport numpy as np\nimport numpy.typing as npt\n\n\n@dataclass\nclass HopfieldStore:\n    \"\"\"Continuous (modern) Hopfield network for embedding-shaped patterns.\"\"\"\n\n    dim: int\n    beta: float = 8.0\n    patterns: list[npt.NDArray[np.float32]] = None  # type: ignore[assignment]\n\n    def __post_init__(self) -> None:\n        if self.patterns is None:\n            self.patterns = []\n        if self.dim <= 0:\n            raise ValueError(\"HopfieldStore.dim must be positive\")\n        if self.beta <= 0:\n            raise ValueError(\"HopfieldStore.beta must be positive\")\n\n    @property\n    def n_patterns(self) -> int:\n        return len(self.patterns)\n\n    def store(self, pattern: npt.NDArray[np.float32]) -> None:\n        if pattern.shape != (self.dim,):\n            raise ValueError(f\"pattern shape {pattern.shape} != ({self.dim},)\")\n        normalized = pattern / (np.linalg.norm(pattern) + 1e-12)\n        self.patterns.append(normalized.astype(np.float32))\n\n    def _matrix(self) -> npt.NDArray[np.float32]:\n        if not self.patterns:\n            return np.zeros((0, self.dim), dtype=np.float32)\n        return np.stack(self.patterns, axis=0).astype(np.float32)\n\n    def recall(\n        self,\n        cue: npt.NDArray[np.float32],\n        *,\n        max_iter: int = 50,\n        tol: float = 1e-5,\n    ) -> npt.NDArray[np.float32]:\n        if not self.patterns:\n            return cue.astype(np.float32) / (np.linalg.norm(cue) + 1e-12)\n        x = cue.astype(np.float32) / (np.linalg.norm(cue) + 1e-12)\n        X = self._matrix()\n        prev = x\n        for _ in range(int(max_iter)):\n            scores = self.beta * (X @ x)\n            scores -= scores.max()  # logsumexp stability\n            weights = np.exp(scores)\n            weights /= weights.sum() + 1e-30\n            x = (X.T @ weights).astype(np.float32)\n            x = x / (np.linalg.norm(x) + 1e-12)\n            if float(np.linalg.norm(x - prev)) < tol:\n                break\n            prev = x\n        return x\n\n    def consolidate_sws(\n        self,\n        traces: list[npt.NDArray[np.float32]],\n        *,\n        n_centroids: int = 4,\n        n_iter: int = 25,\n        seed: int = 0,\n    ) -> list[npt.NDArray[np.float32]]:\n        \"\"\"SWS-like schema abstraction: k-means on `traces`, return centroids.\n\n        Each centroid is then *stored* back into the Hopfield network, simulating\n        the SWS-style abstraction-and-replay pattern.\n        \"\"\"\n        if not traces:\n            return []\n        rng = np.random.default_rng(int(seed))\n        X = np.stack([t / (np.linalg.norm(t) + 1e-12) for t in traces], axis=0).astype(np.float32)\n        k = int(min(n_centroids, len(traces)))\n        # k-means++ init.\n        idx = [int(rng.integers(0, len(traces)))]\n        for _ in range(1, k):\n            # Cosine distance to nearest centroid so far. Clip to [0, 2] to absorb\n            # the tiny negative-cosine drift that arises when rounded unit vectors\n            # produce dot-products slightly above 1.\n            dists = np.clip(\n                np.min(1.0 - X @ X[idx].T, axis=1).astype(np.float64),\n                0.0,\n                2.0,\n            )\n            total = float(dists.sum())\n            if total <= 1e-12:\n                # All remaining traces are degenerate copies of the seeds; fall\n                # back to uniform sampling so we still draw k distinct indices.\n                probs = np.ones(len(traces), dtype=np.float64) / float(len(traces))\n            else:\n                probs = (dists / total).astype(np.float64)\n            idx.append(int(rng.choice(len(traces), p=probs)))\n        centroids = X[idx].copy()\n        for _ in range(int(n_iter)):\n            sims = X @ centroids.T  # (n, k)\n            assign = np.argmax(sims, axis=1)\n            new_centroids = centroids.copy()\n            for c in range(k):\n                members = X[assign == c]\n                if len(members) > 0:\n                    new = members.mean(axis=0)\n                    new_centroids[c] = new / (np.linalg.norm(new) + 1e-12)\n            if np.allclose(new_centroids, centroids, atol=1e-6):\n                centroids = new_centroids\n                break\n            centroids = new_centroids\n        out = [c.astype(np.float32) for c in centroids]\n        for c in out:\n            self.store(c)\n        return out\n\n    def consolidate_rem(\n        self,\n        *,\n        n_steps: int = 100,\n        temperature: float = 1.5,\n        seed: int = 0,\n    ) -> list[npt.NDArray[np.float32]]:\n        \"\"\"REM-like cross-basin replay: random walk between attractors at high temperature.\n\n        Implements a Metropolis-style hop between stored basins by perturbing\n        a random pattern with isotropic Gaussian noise and recalling at a\n        higher beta-effective (temperature). Returns the trajectory.\n        \"\"\"\n        if not self.patterns:\n            return []\n        rng = np.random.default_rng(int(seed))\n        beta_orig = self.beta\n        try:\n            self.beta = max(beta_orig / float(temperature), 0.5)\n            x = self.patterns[int(rng.integers(0, self.n_patterns))].copy()\n            traj: list[npt.NDArray[np.float32]] = []\n            for _ in range(int(n_steps)):\n                noise = rng.normal(0.0, 0.1 * float(temperature), size=self.dim).astype(np.float32)\n                x = x + noise\n                x = self.recall(x, max_iter=20)\n                traj.append(x.copy())\n            return traj\n        finally:\n            self.beta = beta_orig\n",
 "pce-poem/pce/substrate/http_embed.py": "\"\"\"Embedder backed by the neo-fm embedding service (multilingual-e5-small on Cloud Run).\n\nSame interface as the lexical stand-in. Raw e5 cosines are compressed into ~[0.7, 0.9] (anisotropy), which would\nflatten every threshold in the operators, so vectors are mean-centred on a fixed multilingual reference set and\nre-normalised: cosine then spreads over roughly [-0.5, 1].\nEnv: EMBED_URL, EMBED_TOKEN.\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport os\nimport urllib.request\nfrom typing import overload\n\nimport numpy as np\nimport numpy.typing as npt\n\nfrom pce.substrate.embed import Embedder as LexicalEmbedder\n\n_REFERENCE = [\n    \"The market was crowded and loud.\", \"She walked home slowly in the evening.\", \"A river runs through the old town.\",\n    \"The festival begins at dawn.\", \"He repaired the broken clock.\", \"Children played in the courtyard.\",\n    \"ಬೆಳಗಿನ ಗಾಳಿಯಲ್ಲಿ ಹೂವಿನ ಪರಿಮಳ\", \"ಅವನು ಊರಿಗೆ ಹೋದನು\", \"ಹಳ್ಳಿಯ ಜಾತ್ರೆ ಸಂಜೆ ಶುರುವಾಯಿತು\",\n    \"காலையில் கோவில் மணி ஒலித்தது\", \"அவள் ஆற்றங்கரையில் நடந்தாள்\", \"ఉదయం మార్కెట్ రద్దీగా ఉంది\",\n    \"बारिश के बाद सड़क गीली थी\", \"वह शाम को घर लौटा\", \"त्योहार की तैयारी चल रही है\",\n    \"সন্ধ্যায় নদীর ধারে হাওয়া বইছে\", \"മഴ പെയ്തു കഴിഞ്ഞ് മുറ്റം നനഞ്ഞു\",\n    \"Numbers and tables were added to the report.\", \"The engine needs oil and a new filter.\",\n    \"A song about courage and a long road.\", \"Quiet streets before the first train.\",\n    \"Two friends argued about a cricket match.\", \"The recipe calls for ginger and cumin.\", \"Old letters in a wooden box.\",\n]\n\n\nclass Embedder(LexicalEmbedder):\n    def __init__(self, url: str | None = None, token: str | None = None) -> None:\n        super().__init__(model_id=\"multilingual-embedding@service\")\n        self.url = (url or os.environ[\"EMBED_URL\"]).rstrip(\"/\")\n        self.token = token or os.environ[\"EMBED_TOKEN\"]\n        self._cache: dict[str, npt.NDArray[np.float32]] = {}\n        raw = self._fetch(_REFERENCE)\n        self._mu = raw.mean(axis=0)\n        self.dim = int(raw.shape[1])\n\n    def _fetch(self, texts: list[str]) -> npt.NDArray[np.float32]:\n        out: list[list[float]] = []\n        for i in range(0, len(texts), 32):\n            req = urllib.request.Request(\n                self.url + \"/embed\", method=\"POST\",\n                data=json.dumps({\"texts\": texts[i : i + 32], \"kind\": \"similarity\"}).encode(),\n                headers={\"Authorization\": f\"Bearer {self.token}\", \"content-type\": \"application/json\"},\n            )\n            with urllib.request.urlopen(req, timeout=60) as r:  # noqa: S310 - fixed https endpoint\n                out.extend(json.loads(r.read())[\"vectors\"])\n        return np.asarray(out, dtype=np.float32)\n\n    def _centred(self, raw: npt.NDArray[np.float32]) -> npt.NDArray[np.float32]:\n        v = raw - self._mu\n        return (v / np.clip(np.linalg.norm(v, axis=-1, keepdims=True), 1e-9, None)).astype(np.float32)\n\n    def _vectors(self, items: list[str]) -> npt.NDArray[np.float32]:\n        missing = [t for t in dict.fromkeys(items) if t not in self._cache]\n        if missing:\n            for t, v in zip(missing, self._centred(self._fetch(missing)), strict=True):\n                self._cache[t] = v\n        return np.stack([self._cache[t] for t in items])\n\n    @overload\n    def encode(self, text: str) -> npt.NDArray[np.float32]: ...\n    @overload\n    def encode(self, text: list[str]) -> npt.NDArray[np.float32]: ...\n\n    def encode(self, text: str | list[str]) -> npt.NDArray[np.float32]:\n        if isinstance(text, str):\n            return self._vectors([text])[0]\n        items = list(text)\n        if not items or any(not isinstance(t, str) for t in items):\n            raise ValueError(\"Embedder.encode requires a string or list[str]\")\n        return self._vectors(items)\n",
 "pce-poem/pce/substrate/lm.py": "\"\"\"Cloud port: the local Qwen substrate is not shipped. `LocalLM` stays importable as a type only.\"\"\"\nfrom __future__ import annotations\n\n\nclass LocalLM:  # pragma: no cover - placeholder so `cascade` keeps its original signature\n    def __init__(self, *_: object, **__: object) -> None:\n        raise RuntimeError(\"LocalLM is not available in the cloud port; use ReplayLM\")\n",
 "pce-poem/pce/substrate/lm_protocol.py": "\"\"\"Pluggable LM substrate contract.\n\nPer [docs/adr/v0.3/ADR-001-clean-haiku-cli.md](../../../docs/adr/v0.3/ADR-001-clean-haiku-cli.md)\nthe protocol is renamed `GeneratorProtocol` (with `LMProtocol` kept as an alias for\nbackward compatibility) and gains capability flags so callers can interrogate what\nthe substrate honestly exposes.\n\nTwo implementations ship:\n\n* `LocalLM` (existing, see `lm.py`) — `Qwen/Qwen2-1.5B-Instruct` via `transformers`.\n  Advertises `supports_logprobs=True`, `supports_score=True`, `supports_entropy=False`.\n* `HaikuLM` (see `haiku_lm.py`) — Anthropic Claude Haiku via the `claude` CLI in a\n  clean-substrate inner subprocess (no API key). Advertises all capability flags as\n  `False`; exposes `length_proxy_logp` so callers cannot mistake length for real logprobs.\n\nFuture substrates implement this Protocol and the cascade picks them up\nwithout further changes.\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Any, Protocol, runtime_checkable\n\nfrom pce.types import Candidate\n\n\n@runtime_checkable\nclass GeneratorProtocol(Protocol):\n    \"\"\"Substrate the cascade calls into.\n\n    Implementations are responsible for:\n\n    * deterministic behavior under `seed` to the extent possible (cloud LMs\n      without seed control should still be deterministic in their prompt\n      construction, see `HaikuLM._seed_prefix`);\n    * cost telemetry via `audit/<substrate>/<ts>.json` and updates to\n      `audit/cost_ledger.json` when the substrate incurs real cost;\n    * graceful failure (raise a clear `RuntimeError` rather than fall back\n      silently to a different substrate or a mock).\n\n    Capability flags let callers interrogate what the substrate honestly exposes.\n    The cascade and active-inference modules (`pce.active_inference.budget`,\n    `pce.operators.jnana`) consult these flags so they never rely on a signal the\n    substrate cannot provide. See ADR-001 (clean-haiku-cli) and ADR-005\n    (free-energy-budget) for the v0.3 contract.\n    \"\"\"\n\n    name: str\n    \"\"\"Stable substrate identifier, e.g. 'qwen2-1.5b' or 'claude-haiku'.\"\"\"\n\n    supports_logprobs: bool\n    \"\"\"True iff `Candidate.logp` is a real log-probability from the substrate.\"\"\"\n\n    supports_score: bool\n    \"\"\"True iff the substrate can score arbitrary completions out-of-band.\"\"\"\n\n    supports_entropy: bool\n    \"\"\"True iff the substrate exposes per-token entropy or top-k logits.\"\"\"\n\n    def generate(\n        self,\n        prompt: str,\n        *,\n        max_tokens: int,\n        sampler: dict[str, float],\n        seed: int,\n    ) -> Candidate:\n        \"\"\"Produce one Candidate.\n\n        Sampler keys: ``tau`` (temperature), ``top_p``, ``top_k``. Implementations\n        may ignore keys they cannot honor and record what they did honor in\n        ``Candidate.sampler``.\n\n        ``Candidate.embedding`` may be left as a sentinel (``np.zeros(0,\n        dtype=np.float32)``); the cascade re-embeds via the shared ``Embedder``\n        for cross-substrate consistency.\n        \"\"\"\n        ...\n\n    def length_proxy_logp(self, candidate: Candidate) -> float:\n        \"\"\"A calibrated, *honest* fallback when `supports_logprobs` is False.\n\n        For substrates that do not expose real log-probabilities, this returns a\n        deterministic monotone proxy (typically `-output_tokens * log(2)`) so that\n        downstream code which only uses `logp` as a tie-breaker stays stable. Callers\n        must not interpret the return value as a true log-probability.\n        \"\"\"\n        ...\n\n    def report(self) -> dict[str, Any]:\n        \"\"\"Substrate diagnostic: model id, dtype, device, etc.\"\"\"\n        ...\n\n\n# Backward-compatible alias used throughout v0.1/v0.2 code.\nLMProtocol = GeneratorProtocol\n",
 "pce-poem/pce/substrate/replay_lm.py": "\"\"\"ReplayLM: lets the unmodified `run_cascade` run when the *agent* is the language model.\n\nGeneration happens outside this process (the agent / worker subagents write candidate texts to a JSON\nfile). The cascade asks for K draft candidates, then K revision candidates; whichever pass lacks\ntexts raises `NeedGeneration`, which the driver turns into a request for the agent.\n\"\"\"\nfrom __future__ import annotations\n\nimport numpy as np\n\nfrom pce.types import Candidate\n\n\nclass NeedGeneration(Exception):\n    def __init__(self, kind: str, have: int, prompt: str, seed: int) -> None:\n        super().__init__(f\"need {kind} candidates (have {have})\")\n        self.kind, self.have, self.prompt, self.seed = kind, have, prompt, seed\n\n\nclass ReplayLM:\n    name = \"agent-replay\"\n    supports_logprobs = False\n    supports_score = False\n    supports_entropy = False\n\n    def __init__(self, draft: list[str], revision: list[str], embed: object) -> None:\n        self._embed = embed\n        self._texts = {\"draft\": list(draft), \"revision\": list(revision)}\n        self._used = {\"draft\": 0, \"revision\": 0}\n\n    def generate(self, prompt: str, *, max_tokens: int, sampler: dict[str, float], seed: int) -> Candidate:\n        kind = \"revision\" if \"Reviser brief:\" in prompt else \"draft\"\n        i = self._used[kind]\n        if i >= len(self._texts[kind]):\n            raise NeedGeneration(kind, len(self._texts[kind]), prompt, seed)\n        self._used[kind] = i + 1\n        text = self._texts[kind][i]\n        n = len(text.split())\n        return Candidate(seed=seed, sampler=dict(sampler), tokens=tuple(range(n)), text=text,\n                         logp=-float(n), embedding=np.asarray(self._embed.encode(text), dtype=np.float32))\n\n    def length_proxy_logp(self, candidate: Candidate) -> float:\n        return -float(len(candidate.tokens))\n\n    def report(self) -> dict[str, object]:\n        return {\"name\": self.name, \"model\": \"agent\"}\n\n\nclass RecorderLM:\n    \"\"\"Records the exact (prompt, seed) of every request so the driver can hand the agent all of them at once.\"\"\"\n\n    name = \"recorder\"\n    supports_logprobs = False\n    supports_score = False\n    supports_entropy = False\n\n    def __init__(self) -> None:\n        self.requests: list[tuple[str, int]] = []\n\n    def generate(self, prompt: str, *, max_tokens: int, sampler: dict[str, float], seed: int) -> Candidate:\n        self.requests.append((prompt, seed))\n        return Candidate(seed=seed, sampler=dict(sampler), tokens=(0,), text=\"x\", logp=-1.0,\n                         embedding=np.zeros(1, dtype=np.float32))\n\n    def length_proxy_logp(self, candidate: Candidate) -> float:\n        return -1.0\n\n    def report(self) -> dict[str, object]:\n        return {\"name\": self.name}\n",
 "pce-poem/pce/types.py": "\"\"\"Shared types for the PCE engine.\n\nThese dataclasses are frozen and exhaustive: every operator's input and output\nshape is described here, and `tests/test_types.py` verifies the round-trip\nJSON serialization used by the audit log.\n\"\"\"\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\nimport numpy as np\nimport numpy.typing as npt\n\nEmbeddingArray = npt.NDArray[np.float32]\nPosteriorArray = npt.NDArray[np.float32]\n\n\n@dataclass(frozen=True)\nclass Constraint:\n    \"\"\"A constraint vector pulling icchā candidate generation toward an axis.\"\"\"\n\n    text: str\n    embedding: EmbeddingArray\n    weight: float = 1.0\n    must_avoid: tuple[str, ...] = ()\n\n    def __post_init__(self) -> None:\n        if not isinstance(self.text, str) or not self.text:\n            raise ValueError(\"Constraint.text must be a non-empty string\")\n        if not isinstance(self.embedding, np.ndarray):\n            raise TypeError(\"Constraint.embedding must be a numpy array\")\n        if self.embedding.ndim != 1:\n            raise ValueError(f\"Constraint.embedding must be 1D, got {self.embedding.ndim}D\")\n        if self.weight < 0:\n            raise ValueError(f\"Constraint.weight must be >= 0, got {self.weight}\")\n\n\n@dataclass(frozen=True)\nclass Candidate:\n    \"\"\"One icchā-generated candidate continuation.\"\"\"\n\n    seed: int\n    sampler: dict[str, float]\n    tokens: tuple[int, ...]\n    text: str\n    logp: float\n    embedding: EmbeddingArray\n\n    def __post_init__(self) -> None:\n        if \"tau\" not in self.sampler:\n            raise ValueError(\"Candidate.sampler must include 'tau'\")\n        if self.embedding.ndim != 1:\n            raise ValueError(f\"Candidate.embedding must be 1D, got {self.embedding.ndim}D\")\n\n    def to_audit(self) -> dict[str, Any]:\n        return {\n            \"seed\": self.seed,\n            \"sampler\": dict(self.sampler),\n            \"n_tokens\": len(self.tokens),\n            \"text\": self.text,\n            \"logp\": float(self.logp),\n        }\n\n\n@dataclass(frozen=True)\nclass CascadeState:\n    \"\"\"The full state of one cascade run; the audit-of-record.\n\n    v0.2 (ADR-003): the cascade is two-pass-always, so ``surface`` carries\n    the *revision* output by default and the additional ``surface_draft`` /\n    ``surface_revision`` fields preserve both passes for the H8.v2\n    revision-vs-draft contribution test.\n\n    v0.3 (ADR-002): the cascade is event-gated + always-shadow-revision.\n    ``surface`` is whichever pass the commit policy selected; ``committed``\n    records that choice (``\"revision\"`` or ``\"draft\"``). ``surface_draft``\n    and ``surface_revision`` are *both always populated* under\n    ``commit_policy=\"event_gated\"`` and ``\"always_revise\"``, so H8 stays\n    measurable on every run. ``commit_policy=\"always_draft\"`` (the explicit\n    ablation) skips the revision pass entirely and leaves\n    ``surface_revision is None``.\n    \"\"\"\n\n    prompt: str\n    constraint: Constraint\n    cit_temperature: float\n    candidates: tuple[Candidate, ...]\n    posterior: PosteriorArray\n    selected: Candidate | None\n    surface: str | None\n    vimarsa_event: bool\n    vimarsa_novelty: float\n    aspects: tuple[str, ...]\n    surface_draft: str | None = None\n    surface_revision: str | None = None\n    vimarsa_event_draft: bool = False\n    vimarsa_brief: str | None = None\n    committed: str = \"draft\"\n    commit_policy: str = \"event_gated\"\n    audit: dict[str, Any] = field(default_factory=dict)\n\n    def to_audit(self) -> dict[str, Any]:\n        return {\n            \"prompt\": self.prompt,\n            \"constraint_text\": self.constraint.text,\n            \"constraint_must_avoid\": list(self.constraint.must_avoid),\n            \"cit_temperature\": float(self.cit_temperature),\n            \"n_candidates\": len(self.candidates),\n            \"posterior\": [float(p) for p in self.posterior.tolist()],\n            \"selected_idx\": (\n                self.candidates.index(self.selected) if self.selected is not None else -1\n            ),\n            \"surface\": self.surface,\n            \"surface_draft\": self.surface_draft,\n            \"surface_revision\": self.surface_revision,\n            \"vimarsa_event\": self.vimarsa_event,\n            \"vimarsa_event_draft\": self.vimarsa_event_draft,\n            \"vimarsa_novelty\": float(self.vimarsa_novelty),\n            \"vimarsa_brief\": self.vimarsa_brief,\n            \"committed\": str(self.committed),\n            \"commit_policy\": str(self.commit_policy),\n            \"aspects\": list(self.aspects),\n            \"audit\": dict(self.audit),\n        }\n",
 "pce-poem/run_cascade.py": "#!/usr/bin/env python3\n\"\"\"Driver: runs the Pratyabhijna cascade (vendored `pce` package) with the agent as the language model.\n\nUsage:  python3 run_cascade.py <workdir>\nReads   <workdir>/brief.json        {\"topic\",\"constraint\",\"must_avoid\":[],\"aspects\":[],\"K\":3,\"retrieval_set\":[]}\n        <workdir>/generations.json  {\"draft\":[texts...],\"revision\":[texts...]}   (optional, grows over rounds)\nWrites  <workdir>/needs.json        when the cascade needs more candidate texts (exit code 3)\n        <workdir>/result.json       the committed surface + full audit (exit code 0)\nRound 1 asks for K draft candidates; round 2 (after the draft pass) asks for K revision candidates built\nfrom the cascade's own reviser brief. Nothing is mocked: operators, scoring, vimarsa and the commit\npolicy are the original code.\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport os\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\n\nimport numpy as np  # noqa: E402\n\nfrom pce.cascade import run_cascade  # noqa: E402\nfrom pce.substrate.embed import Embedder as LexicalEmbedder  # noqa: E402\nfrom pce.operators.iccha import PERTURBATION_TABLE, iccha  # noqa: E402\nfrom pce.substrate.replay_lm import NeedGeneration, RecorderLM, ReplayLM  # noqa: E402\nfrom pce.types import Constraint  # noqa: E402\n\n\ndef _load(path: Path, default):\n    return json.loads(path.read_text(encoding=\"utf-8\")) if path.exists() else default\n\n\ndef main(workdir: str) -> int:\n    wd = Path(workdir)\n    brief = json.loads((wd / \"brief.json\").read_text(encoding=\"utf-8\"))\n    gens = _load(wd / \"generations.json\", {\"draft\": [], \"revision\": []})\n    if os.environ.get(\"EMBED_URL\") and os.environ.get(\"EMBED_TOKEN\"):\n        from pce.substrate.http_embed import Embedder  # multilingual service (preferred)\n\n        embed = Embedder()\n    else:\n        embed = LexicalEmbedder()  # offline fallback: lexical only, flagged in result.json\n    constraint = Constraint(\n        text=brief[\"constraint\"],\n        embedding=embed.encode(brief[\"constraint\"]),\n        must_avoid=tuple(brief.get(\"must_avoid\", [])),\n    )\n    # Calibration: the plugin's 0.30-0.40 thresholds were tuned for same-language MiniLM cosines. With the centred\n    # multilingual service embedder, English aspect vs Indic lyric cosines separate cleanly at ~0.15\n    # (bench/embedder_bench.py: positives min 0.06 / mean 0.34, negatives max 0.05).\n    hit = float(brief.get(\"aspect_cosine_hit\", 0.15 if embed.model_id.endswith(\"@service\") else 0.40))\n    _jnana = sys.modules[\"pce.operators.jnana\"]  # (the package attribute `jnana` is the function)\n    _jnana.ASPECT_HIT_FLOOR = min(_jnana.ASPECT_HIT_FLOOR, hit) if embed.model_id.endswith(\"@service\") else _jnana.ASPECT_HIT_FLOOR\n    lm = ReplayLM(gens.get(\"draft\", []), gens.get(\"revision\", []), embed)\n    K = int(brief.get(\"K\", 3))\n    cit_t = float(brief.get(\"cit_temperature\", 1 / 3))  # 1/3 is the neutral point: exactly K candidates per pass\n    try:\n        state = run_cascade(\n            brief[\"topic\"], constraint, lm=lm, embed=embed, K=K,\n            aspects=brief.get(\"aspects\") or None,\n            retrieval_set=brief.get(\"retrieval_set\") or None,\n            cit_temperature=cit_t,\n            aspect_cosine_hit=hit,\n            commit_policy=brief.get(\"commit_policy\", \"event_gated\"),\n            base_seed=int(brief.get(\"seed\", 0)),\n        )\n    except NeedGeneration as need:\n        # Enumerate every request of this pass (each candidate has its own prompt perturbation).\n        base_prompt = need.prompt\n        for pert in PERTURBATION_TABLE:\n            if pert and base_prompt.startswith(pert):\n                base_prompt = base_prompt[len(pert):]\n                break\n        rec = RecorderLM()\n        iccha(base_prompt, constraint, lm=rec, K=K, base_seed=need.seed - need.have, cit_temperature=cit_t)\n        prompts = [p for p, _ in rec.requests]\n        (wd / \"needs.json\").write_text(json.dumps({\n            \"kind\": need.kind, \"have\": need.have, \"need\": len(prompts), \"prompts\": prompts,\n            \"instruction\": f\"Write {len(prompts)} complete candidates, one per entry of `prompts` (in order; candidate i answers prompts[i], \"\n                           f\"honouring its leading nudge), as generations.json['{need.kind}'] = [text, ...]. Same language and form as the brief.\",\n        }, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n        print(f\"NEEDS {need.kind} have={need.have} need={len(prompts)} -> {wd/'needs.json'}\")\n        return 3\n    audit = state.to_audit()\n    result = {\n        \"surface\": state.surface, \"committed\": state.committed, \"vimarsa_event\": state.vimarsa_event,\n        \"vimarsa_novelty\": state.vimarsa_novelty, \"posterior\": [float(p) for p in np.asarray(state.posterior)],\n        \"surface_draft\": state.surface_draft, \"surface_revision\": state.surface_revision,\n        \"embedder\": embed.model_id, \"audit\": audit,\n    }\n    (wd / \"result.json\").write_text(json.dumps(result, ensure_ascii=False, indent=2, default=str), encoding=\"utf-8\")\n    print(f\"DONE committed={state.committed} vimarsa_event={state.vimarsa_event}\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main(sys.argv[1]))\n"
};
export const SKILL_PCE_POEM_MD = SKILL_FILES["pce-poem/SKILL.md"]!;
